-- GENERATED by `wfj generate` from data/quest/quest-0096.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [96003] = { "Richiamare il Malevolo", "Usa l'Occhio dell'Influenza Infinita su Bethra'zel e Mazzogore per assorbirne il potere, poi sferra il colpo mortale.", "Come sospettavo, i vasi si sono fusi in qualcosa di nuovo, qualcosa di potente.\n\nImmagino che, se i vasi catturano energia immagazzinata, debba esserci un modo di usare quel potere a nostro vantaggio. Gli artefatti vili raramente sono sicuri o facili da ottenere, ma tanto vale farne qualcosa, mh?\n\nÈ ora di una prova sul campo.\n\nPrendi il cristallo e usalo contro Bethra'zel e Mazzogore, due dei loro demoni più potenti. La loro sola presenza ha garantito che l'accampamento sia ben protetto. Vediamo se riusciamo a cambiare la cosa.", nil, nil, 0x7aac2899, 0x8889e560, 0x8e5adb4b, nil, nil, "...mm" },
  [96009] = { "Posta alta", "Raccogli $N1 Fascina di Legna dal Campo di Disboscamento di Turner per Bertrand Fronte Dura a Forte Farholde.", "Una cosa che non smette mai di stupirmi è la determinazione degli umani. Vedono una desolata zona di guerra brulicante di orchi e cultisti e pensano che sia il posto perfetto per aprire bottega! Incredibile.\n\nMa non è compito mio dire loro dove costruire. Devo solo mostrare come. E se vogliamo che questo forte sia grande come dicono, ci servirà un sacco di legna.\n\nCon quanto sono diventate pericolose le strade, le nostre spedizioni di legname dalla segheria a nord-ovest rallentano fino a procedere a passo di lumaca. Pensi di poterci portare qualche fascina?", "Il mulino è appena a nord-ovest da qui, se riesci a superare i coccodrilli e i murloc.", "Sì, questi andranno benissimo. A questo ritmo potremmo persino riuscire a finire il cancello.\n\nÈ un bene, anche. Gli orchi diventano più aggressivi ogni giorno.", 0xf67b5cb7, 0xa8b5ecb8, 0x2d0a032b, 0x2cbaee0f, 0x510b2748, "....." },
  [96010] = { "Frammenti dei piloni", "Recupera schegge e frammenti dei piloni, custoditi al Magram Village e al Villaggio dei Gelkis. Riportali a Mordent Vesprombroso.", "Anche se sono certo che il danno a entrambi i piloni possa essere attribuito allo sconsiderato scorrazzare dei centauri, sospetto che i tempi della loro furia abbiano causato la separazione dei frammenti. Conosco poco delle loro dispute, ma so che ci sono almeno due fazioni principali che si sono introdotte a Shen'dralas: i feroci Magram e gli astuti Gelkis.\n\nTenere questi tesori in mezzo a un campo di battaglia sarebbe imprudente. A quest'ora presumo che abbiano portato i loro trofei ai propri villaggi.", "Preferirei non attirare ulteriormente l'attenzione dei centauri su di me o sui miei fratelli caduti, altrimenti andrei a cercare io stesso i cristalli.", "I cristalli sono in qualche pezzo in più di quanto mi aspettassi, ma sembra che ci sia tutto. Per ora li tengo io. Grazie, {name}.\n\nIl tuo prossimo passo sarà raccogliere mana abbastanza malleabile da servire sia da adesivo per i pezzi rotti sia da condotto attraverso cui le linee di potere possano poi fluire.\n\nÈ un processo davvero notevole, ma raccogliere il mana potrebbe rivelarsi scomodo.", 0x23e961a4, 0x95e79125, 0x53c5a4fd, 0xedd9d703, 0xa7107383, "....." },
  [96015] = { "Un problema da minatori", "Sconfiggi $N1 Minatore Ogre e $N2 Soggiogatore del Crepuscolo nella grotta vicino al Velo del Crepuscolo per il sergente Riftan.", "Dovremmo essere grati che il nostro nemico sia stupido. Hanno a disposizione un esercito di ogre e il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ li fa lavorare nelle miniere, lontano dallo scontro. Non so se attribuirlo a cattiva gestione o a una lotta interna, ma in ogni caso non sono in condizione di difendersi.\n\nÈ qui che entriamo in gioco noi. Con l'attenzione del culto divisa, abbiamo l'opportunità di colpire il nemico mentre è vulnerabile e di dividerlo ulteriormente. Vai a questa miniera e semina un po' di caos tra i loro ranghi.", nil, "Non so in che razza di politica ci siamo cacciati, ma un ogre morto è sempre una vittoria per me. Se riusciamo a tenerli in difficoltà, non avranno il tempo di riprendersi.", 0x39bbf3f5, 0xdc1ffb67, 0xae3ba2da, nil, 0xdc84e51e, "...m." },
  [96016] = { "Le armi della tempesta", "Consegna l'⟦Eye of the Tempest=Occhio della Tempesta⟧ a ⟦Bath'rah the Windwatcher=Bath'rah il Guardiavento⟧, nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Hai fatto un buon lavoro, e vedo che non stai più nella pelle per la ricompensa. Mi spiace dirtelo, ma non sono proprio un nano di molti averi.\n\n<Veyric indica con un ampio gesto il luogo sperduto in cui si trova.>\n\nFacciamo così, però. Ho sentito che un troll chiamato l'osservatore dei venti vive tra le ⟦Alterac Mountains=Montagne d'Alterac⟧. È anche lui un potente sciamano, ed esperto di elementali della tempesta. Se gli porti quel nucleo elementale, scommetto che può forgiarti un'arma degna della tua vittoria.", nil, nil, 0x578d0b90, 0x5da19497, 0x67a5ea2f, nil, nil, "...mm" },
  [96018] = { "Alimentare i piloni", "Procurati il Setaccio di Mana dal tempio di Shen'dralas e usalo per raccogliere Cristalli di Mana Antichi. Quando avrai abbastanza mana, potenzia i piloni e torna da Mordent Vesprombroso.", "Potresti aver visto le scintille fluttuanti di mana sparse per Shen'dralas. È un fenomeno nuovo, probabilmente il risultato dei danni subiti dai piloni.\n\nCi serve questo mana indietro in forma semicristallizzata. Possiamo ottenerlo usando il Setaccio di Mana che si trova nel tempio. Prendi in prestito il setaccio e raccogli tutte le sfere di mana fluttuanti che trovi.\n\nGli abitanti del tempio non apprezzeranno che il loro prezioso artefatto venga preso in prestito senza il loro consenso, ma col tempo capiranno.", "È bello rivederti, {name}.", "Vedo che hai riparato con successo i piloni--come potrei non notarlo?\n\n<Mordent indica verso l'alto, in direzione del cielo, e il suo sguardo segue brevemente quella direzione. Quando la sua attenzione torna su di te, inarca un sopracciglio notando il tuo entusiasmo apparentemente scarso.>", 0x877d1e35, 0x9ac2fffe, 0xcb0a6ad5, 0xf7b5425b, 0xedba9689, "....." },
  [96020] = { "Giocare col fuoco", "Completa il rituale dell'Intaglio di Zolfo e porta il risultato a un istruttore degli stregoni.", "<L'intaglio è appena tiepido al tatto, nonostante la carbonizzazione ormai fredda da tempo sul corpo da cui l'hai recuperato.\n\nSembra che quel povero disgraziato non abbia finito qualsiasi cosa stesse cercando di compiere. Sebbene tu non riconosca le iscrizioni sull'idolo, esso richiama la tua magia del fuoco. Forse puoi riuscire dove lui ha fallito.>", nil, nil, 0x110d1cb3, 0xe72e68ef, 0x770a4d29, nil, nil, "...mm" },
  [96025] = { "In linea d'aria", "Incontra l'amico di Elaena in cima, a Hyjal.", "Grazie per il tuo aiuto, {name}. Una mia cara amica ti attende alla sommità.\n\nLa trovi lungo la strada a est.", nil, nil, 0xca8d1b90, 0xed856e93, 0xf8757673, nil, nil, "...mm" },
  [96026] = { "Secondo passo: altre pietre", "Consegna $N1 Pietra da Contrappeso Pesante a Hamur a Bolder'ok.", "Questa buona pietra. Ora serve tocco finale. Più pietra.\n\nSolo pietra può rendere pietra più forte. Quella è la via delle pietre.\n\nIo vedo alcuni piccoli fare pietra extra pesante. Portami pietre pesanti e io faccio arma.", nil, nil, 0xfeb09358, 0xba014bbc, 0x879784af, nil, nil, "...mm" },
  [96027] = { "La forza sulla magia", "Uccidi $N1 Predatore delle Pianure per Bal'mog a Bolder'ok.", "Bal intrappolato con testa fastidiosa. Mog segue ovunque Bal va. Fastidioso!\n\nLui dice magia più forte. Per favore. Senza Bal, Mog lancia magia su niente!\n\nBal non ha bisogno di Mog! Bal mostra che pugno basta! Uccidiamo molti piccoli. Mostriamo a Mog che pugno è meglio.", nil, nil, 0xc65b7740, 0x728154ad, 0x5562c148, nil, nil, "...mm" },
  [96028] = { "La magia sulla forza", "Usa $N1 magia per Bal'mog a Bolder'ok.", "Bal stupido. Lui vuole solo colpire cose.\n\nMog intelligente. Mog impara magia per rendere Bal'mog più forte.\n\nMostriamo a Bal che lui stupido. Usiamo magia. Usiamo magia per mostrare che Mog meglio!", nil, nil, 0xab172db5, 0x1e2d01e0, 0xb3430a86, nil, nil, "...mm" },
  [96031] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con ⟦Gretta Finespindle=Gretta Filofino⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, 0x444c023e, 0x86e620e9, nil, nil, "...mm" },
  [96044] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con ⟦Tognus Flintfire=Tognus Fiammaselce⟧ a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0xcccec145, 0x469a706e, nil, nil, "...mm" },
  [96045] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Vosur Brakthel a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Ora che ti sei dedicat<o/a> all'Alchimia, posso anche insegnarti a costruire un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento, una volta che avrai imparato un po' il mestiere. Costruiscine uno, e tutti i guaritori e quelli che lanciano incantesimi accorreranno per un sorso rinfrescante.", nil, "Ecco fatto, ora puoi creare il tuo Pozzo di Mana. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x32f4ba12, 0xfd210ba1, 0xd857517b, nil, 0xbd7a9e72, "...m." },
  [96046] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con ⟦Yarr Hammerstone=Yarr Sassomartello⟧ a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, "Ecco fatto: ora sai fabbricare una Magnetite tutto tuo. Alla gente non piace granché vedere accampamenti nel bel mezzo del paese, quindi se vuoi provarlo dovrai spingerti nelle terre selvagge.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, ti conviene passare da qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0xa8fe12f3, 0xc44564fc, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [96047] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Thamner Pol a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora sai fabbricare un Kit di ⟦First Aid=Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti nel bel mezzo del paese, quindi se vuoi provarlo dovrai spingerti nelle terre selvagge.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, ti conviene passare da qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0x6e7c255b, 0xdf8f53b4, 0x32ff3188, nil, 0x3a282524, "...m." },
  [96050] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con Paxton Ganter vicino al ⟦Iceflow Lake=Lago di Ghiacciospesso⟧, a Dun Morogh, per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, 0x475dee95, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [96055] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con ⟦Reyna Stonebranch=Reyna Brancapietra⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, 0x8a8b95de, 0xe0048777, nil, 0x52608ebe, "...m." },
  [96056] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con ⟦Balthus Stoneflayer=Balthus Sventrapietra⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto, ora puoi creare il tuo Sedia da Campo. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x14236b38, 0x9b6727a8, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [96057] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Uthrar Threx a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, "Ecco fatto: ora puoi costruire il tuo Rallying Banner personale. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa istruirti nelle arti culinarie per imparare le basi.", 0xde7f398c, 0xf651cfe5, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [96058] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con ⟦Bronk Guzzlegear=Bronk Acquavite⟧ a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, "Ecco fatto: ora sai fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ tutto tuo. Alla gente non piace granché vedere accampamenti nel bel mezzo del paese, quindi se vuoi provarlo dovrai spingerti nelle terre selvagge.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, ti conviene passare da qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0x1cb4025b, 0x1d43c051, 0x549b28c0, nil, 0xdc6f9e78, "...m." },
  [96059] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con ⟦Thonys Pillarstone=Thonys Pernoforte⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Ora che hai intrapreso il cammino dell'incantatore, credo di poterti insegnare a costruire un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento, una volta che avrai imparato il mestiere.\n\nÈ davvero importante trovare uno svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0xa6eed0e9, 0x4457b10b, nil, nil, "...mm" },
  [96060] = { "Aspettative temprate", "Usa la Lama Fantasmale per giustiziare $N1 animali selvatici a Shen'dralas, poi torna da Vindael al tempio.", "Lascia che sia il primo a dirti che in vita ero un maestro spadaccino. Forgiavo armi di giorno e le impugnavo di notte.\n\nCome ben sai, il mio rapporto con questa lama in particolare è ormai straordinariamente complicato. Anche se credo di poterla brandire, non sono convinto che servirebbe a molto se non combattendo altri spiriti. Ha davvero un valore per me a Shen'dralas?\n\nCiononostante, vorrei che le sue capacità venissero messe alla prova e penso che le nostre foreste gradirebbero una leggera sfoltita.", nil, nil, 0x7a691a0d, 0x9f7235cd, 0x7fdbbf59, nil, nil, "...mm" },
  [96063] = { "Oro Gassoso", "Raccogli $N1 ⟦Marsh Gas Vial=Fiala di Gas di Palude⟧ per ⟦Sleebo Fizzlespout=Sleebo Sprizzafrizzo⟧.", "Il carburante del futuro non è il carbone, né il petrolio: è il gas, bello mio! Quegli stagni paludosi a sud-ovest ne sputano a tonnellate, e io ho proprio l'invenzione giusta per sfruttarlo: un nuovo tipo di motore che va a gas. Raccoglierlo però è una vera seccatura.\n\nSe ti va di dare un umile contributo al futuro della scienza e dell'industria, perché non mi aiuti a procurarmi un po' di quel gas? Lo vedi uscire dalle bocche vicino all'acqua.", "Spero non ti dispiaccia se ti dico solo lo stretto necessario sui dettagli più fini della mia invenzione. Devo proteggere i miei segreti commerciali, sai?", "Eccellente! Questi andranno proprio bene. Ora, che ne dici di un ultimo favore?", 0x15fabd2d, 0xc4fab564, 0xb3c1cb4c, 0x9f327ee2, 0xcd4af353, "....." },
  [96067] = { "Mena e stendi", "Aiuta Sleebo a testare la sua creazione.", "Avrai notato il mio compagno meccanico, G45-B4G. Dentro quel suo petto di juta gira l'unico, e solo, prototipo funzionante del mio motore a gas.\n\nSecondo me ha bisogno di un test di stress. Ti va di sfidarlo in combattimento? Posso alimentarlo con il gas che hai raccolto.\n\nAh, e non preoccuparti di fargli male. Non sente niente!", nil, nil, 0x92a61d66, 0x8ec7f3bb, 0x2c61205f, nil, nil, "...mm" },
  [96075] = { "Richiestissimo - Registri legali di ⟦Blackrock=Roccianera⟧", "Procurati il Mandato di Nefarian dal ⟦General Drakkisath=Generale Drakkisath⟧ ai ⟦Blackrock Spire=Bastioni di Roccianera⟧, la Licenza del Sovrintendente dal ⟦Overlord Wyrmthalak=Supremo Dragthalak⟧ ai ⟦Blackrock Spire=Bastioni di Roccianera⟧ e il Contratto di Nozze dei Barbabronzea dall'Imperatore Thaurissan nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧, e portali a Pix Xizzix a ⟦Booty Bay=Baia del Bottino⟧.", "I miei datori di lavoro vogliono mettere le mani su documenti legali relativi alla proprietà del ⟦Blackrock Mountain=Massiccio Roccianera⟧. Una specie di disputa sulla proprietà. In ogni caso, se riuscissi a procurare questi documenti chiave, posso permettermi di ricompensarti generosamente.\n\nRecupera il Mandato di Nefarian dal ⟦General Drakkisath=Generale Drakkisath⟧ nella parte superiore dei ⟦Blackrock Spire=Bastioni di Roccianera⟧, una Licenza del Sovrintendente dal ⟦Overlord Wyrmthalak=Supremo Dragthalak⟧ nella parte inferiore dei ⟦Blackrock Spire=Bastioni di Roccianera⟧ e un Contratto di Nozze dei Barbabronzea dall'Imperatore Thaurissan nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.", nil, nil, 0xdba4ab5d, 0x5d08b40f, 0xd3fdfbac, nil, nil, "...mm" },
  [96076] = { "Richiestissimo - Curiosità elfiche antiche", "Recati a ⟦Dire Maul=Maglio Infausto⟧ per ottenere un Seme di Vilvite da ⟦Alzzin the Wildshaper=Alzzin il Selvatico⟧, un Cimelio Antico dal principe Tortheldrin e un Mignolo di Diamante Pietraterra da re Gordok, e portali a Pix Xizzix a ⟦Booty Bay=Baia del Bottino⟧.", "I miei datori di lavoro vogliono mettere le mani su curiosità magiche provenienti dalla città elfica in rovina di Eldre'Thalas, ora nota come ⟦Dire Maul=Maglio Infausto⟧. Una specie di ricerca magica. In ogni caso, se riuscissi a procurare questi oggetti, posso permettermi di ricompensarti generosamente.\n\nRecupera un Seme di Vilvite da ⟦Alzzin the Wildshaper=Alzzin il Selvatico⟧ nell'ala orientale, un Cimelio Antico dal principe Tortheldrin nell'ala occidentale e un Mignolo di Diamante Pietraterra dal re Gordok nell'ala settentrionale.", nil, nil, 0x71524e47, 0xcc43b67e, 0x6a92f373, nil, nil, "...mm" },
  [96077] = { "L'anello di Belle", "Consegna l'anello a Michelle Belle alla Locanda del Fiero Leone nella ⟦Elwynn Forest=Foresta di Elwynn⟧.", "Sì, Thomas Belle.\n\n<L'atteggiamento di Daythor cambia all'improvviso, come se ricordasse un caro ricordo di quella persona.>\n\nThomas è stato uno dei primi a cadere quando il Flagello ha assediato il nostro avamposto. Non avevo saputo della sua scomparsa finché la battaglia non è finita. Tragico... Era un giovane così promettente.\n\nImmagino sia giusto che consegniamo questo alla sua amata Michelle. Se la memoria non mi inganna, parlava spesso di ⟦Goldshire=Borgodoro⟧.", nil, nil, 0x70873c99, 0x6914e5b6, 0x91c0bc02, nil, nil, "...mm" },
  [96078] = { "Un Racconto Intorno al Fuoco", "Porta le incisioni della tavoletta a ⟦Master Gadrin=Maestro Gadrin⟧, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, in Durotar.", "{name}, noi ⟦Darkspear=Lanciascura⟧ teniamo vive molte delle nostre tradizioni raccontandole a voce. Tramandiamo leggende come questa alla generazione successiva, insegnando lezioni e intrecciando racconti ammonitori per i nostri piccoli.\n\nQueste incisioni vanno portate alla nostra guida spirituale, ⟦Master Gadrin=Maestro Gadrin⟧, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧. È uno dei ⟦Darkspear=Lanciascura⟧ più saggi e vorrà conoscere la verità di questo racconto.\n\nHo preparato anche una copia in più del racconto per te. Se mai dovessi perderla, sarò felice di fartene un'altra, per un piccolo compenso.", nil, nil, 0xab004595, 0x10eeb9cc, 0x5a70044a, nil, nil, "...mm" },
  [96081] = { "Medicazioni per ferite", "Raccogli 20 ⟦Mageweave Cloth=Tessuto di Telamagica⟧ per il fratello Lowley a Forte Farholde.", "Se c'è una cosa di cui una forza combattente ha sempre bisogno, sono le bende. Purtroppo Farholde non ha un modo affidabile per produrre stoffa. Perciò dipendiamo dalle importazioni dei goblin o, se siamo fortunati, da ciò che riusciamo a riprendere agli orchi.\n\nAl momento la nostra scorta di stoffa di qualità sta finendo. Dovrò presto cominciare a fare bende con vecchie camicie. Se hai i mezzi per aiutarci, salveresti molte vite.", nil, nil, 0xa013f7ac, 0x6907c997, 0xf5682b7a, nil, nil, "...mm" },
  [96082] = { "L'inserviente del dottore", "Benda 3 Soldato Ferito per il fratello Lowley.", "Trasformerò in bende la stoffa che mi hai dato. Nel frattempo, prendi queste che ho già preparato e medica le ferite dei soldati che ne hanno bisogno. Dovrebbe bastare un po' di primo soccorso di base.\n\nIl tuo aiuto qui è necessario e molto apprezzato. Semplicemente non posso essere ovunque allo stesso tempo.", "Come stanno i soldati?", "Buon lavoro. Per ora basterà.\n\nAlmeno finché le loro ferite non si riapriranno, o non arriveranno nuovi soldati...\n\n<Fratello Lowley si massaggia le tempie per un momento prima di riassumere il suo contegno stoico.>", 0x813c39d3, 0xd861f5a5, 0x639e062f, 0x99e0957c, 0x9caf1e7f, "....." },
  [96083] = { "Quarantena clericale", "Parla con sorella Rowland nella cappella di Forte Farholde.", "Per ora hai fatto tutto il possibile qui.\n\nSe desideri dare ulteriore aiuto, sali la collina fino alla cappella. È l'edificio più piccolo fuori dalla chiesa principale.\n\nSorella Rowland si sta occupando di alcuni soldati in quarantena che hanno contratto una malattia sconosciuta.", nil, "Ah, quindi ti ha mandato Fratello Lowley? Faccio fatica a credere che possa fare a meno di manodopera. Questo significa che hai svolto bene i tuoi compiti.", 0x04053102, 0xcd5704ef, 0x124e53da, nil, 0xc1bc6e33, "...m." },
  [96084] = { "C'è qualcosa nell'acqua", "Raccogli un campione di acqua potabile dalle pianure per sorella Rowland nella cappella di Forte Farholde.", "Ti risparmio i dettagli macabri, ma questi soldati sono gravemente malati. La natura della loro malattia mi porta a credere che ci sia un problema con il cibo o con l'acqua.\n\nHo già controllato i raccolti in arrivo dalle fattorie vicine, quindi resta solo l'acqua, che proviene dai fiumi locali. Il posto migliore per raccogliere un campione sono le pozze nelle pianure a nord. Quasi ogni fiume attraversa quella zona, quindi sarebbe saggio verificare lì la presenza di contaminazione.", "Senza conoscere la causa della loro malattia, posso fare solo fino a un certo punto per curare queste persone.", "Sembra... disgustoso. Cosa potrebbe causare questo genere di contaminazione?", 0xc9842e6c, 0x8ac004f6, 0x14f3164a, 0x66b58073, 0xcb4e07a2, "....." },
  [96085] = { "Contaminazione a monte", "Trova la creatura che sta contaminando l'acqua potabile ed eliminala. Poi torna da sorella Rowland nella cappella di Forte Farholde.", "Le impurità in questo campione sembrano di natura organica. Non proprio rifiuti, ma di certo qualcosa di tossico.\n\nDi fauna selvatica non ne so molto, ma immagino che ci sia qualcosa a monte che causa la contaminazione dell'acqua. Una sorta di animale, o almeno una creatura.\n\nSegui i fiumi più a nord che puoi e vedi se riesci a trovare cosa ne è responsabile. Se è un animale, va abbattuto. È per la sicurezza di tutti qui a Farholde.", nil, nil, 0x70e2ad07, 0xc2fea7b0, 0x1bb9e62f, nil, nil, "...mm" },
  [96087] = { "Richiestissimo - Registri della peste", "Procurati i Registri del Rettore dal ⟦Darkmaster Gandling=Maestro Oscuro Gandling⟧, gli Ordini di Spedizione del Grano dal ⟦Baron Rivendare=Barone Fieramorte⟧ e la Corrispondenza di Dathrohan dal Gran Crociato Saidan Dathrohan, e portali a Pix Xizzix a ⟦Booty Bay=Baia del Bottino⟧.", "Un gruppo di storici mi ha incaricato di recuperare i registri della grande piaga. Dimostrare chi è colpevole e chi no, o qualcosa del genere. Procurami alcuni di questi documenti e ti ricompenserò generosamente.\n\nRecupera i Registri del Rettore dal ⟦Darkmaster Gandling=Maestro Oscuro Gandling⟧ nella Scholomance, gli Ordini di Spedizione del Grano dal ⟦Baron Rivendare=Barone Fieramorte⟧ nella città sempre in fiamme di Stratholme e la Corrispondenza di Dathrohan dal Gran Crociato Saidan Dathrohan nel Bastione Scarlatto di Stratholme.", nil, nil, 0xcebe4226, 0xc08b52c8, 0x8497d0b0, nil, nil, "...mm" },
  [96088] = { "Richiestissimo - Reliquie dei Titani", "Procurati la Lacrima di Ysera dall'⟦Shade of Eranikus=Ombra di Eranikus⟧ nel Tempio di Atal'Hakkar, un Marchio di Xavius da Varrox Zoccolotetro nella ⟦Blackmaw Hold=Tana degli Zannanera⟧ e il Sigillo di Freya da Nanaya nella Terrazza del Plasmatore, e portali a Pix Xizzix a ⟦Booty Bay=Baia del Bottino⟧.", "Alcuni ricercatori di Dalaran cercano reliquie dei Titani e dei loro seguaci, nonché dei loro nemici della Legione Infuocata. Le reliquie si trovano in posti difficili che non posso raggiungere. Recuperale per me e ti ricompenserò generosamente.\n\nRecupera la Lacrima di Ysera dall'⟦Shade of Eranikus=Ombra di Eranikus⟧ nel Tempio di Atal'Hakkar, un Marchio di Xavius da Varrox Zoccolotetro nella ⟦Blackmaw Hold=Tana degli Zannanera⟧ e il Sigillo di Freya da Nanaya nella Terrazza del Plasmatore.", nil, nil, 0xc699e752, 0xa0a7edc3, 0xd6749c2a, nil, nil, "...mm" },
  [96101] = { "La vita all'aria aperta", "Siediti vicino al ⟦Raan's Basic Campfire=Fuoco da Campo Semplice di Raan⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Possedere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xeb724be6, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96102] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Snang a Orgrimmar per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0xb3ef6f61, 0x49663bd1, nil, nil, "...mm" },
  [96103] = { "Un banchetto per gli avvoltoi", "Porta il Teschio Rosicchiato a Neza Grugnorosso a Rog'mar.", "Lo scheletro è ridotto a brandelli. Segni profondi sugli arti corrispondono vagamente a impronte di denti e artigli. Molti giorni sotto il sole cocente hanno reso le ossa anche pallide e fragili. La brutalità sia dell'aggressore sia del clima ha reso un mistero l'identità della vittima.\n\nNon puoi portare via l'intero scheletro, ma potresti portare il suo teschio a un cacciatore a Rog'mar e vedere cosa sa.", nil, nil, 0x3042c70f, 0xdf9a1667, 0x18ee6f7e, nil, nil, "...mm" },
  [96104] = { "Il canto dello zampalunga", "Porta un Becco di Zampalunga Intatto a Neza Grugnorosso a Rog'mar.", "Questi segni sono di un leone. A giudicare da essi, questo è particolarmente grosso: il capo del vicino branco.\n\nCaccerei volentieri io stesso la bestia, ma tu hai la precedenza. Io invece ti aiuterò.\n\nPosso fabbricare un fischietto che imita il richiamo di uno zampalunga ferito. Puoi usarlo per attirare fuori il leone. Mi serve solo uno dei loro becchi per dargli il suono giusto.\n\nCi sono zampalunga per tutte le pianure. Trovami un becco e la caccia potrà cominciare!", nil, nil, 0x37a5cbb4, 0x893a6968, 0x5de39716, nil, nil, "...mm" },
  [96105] = { "Re delle pianure selvagge", "Usa il Richiamo per Zampalunga per attirare il capo del branco di leoni. Uccidi la bestia e recupera la sua pelle per Neza Grugnorosso a Rog'mar.", "Il fischietto è pronto, {name}.\n\nPrendilo e vai in cima alla collina a sud dove vivono i leoni.\n\nQuando sei pront<o/a> ad affrontare la tua preda, soffia nel fischietto e la bestia dovrebbe apparire.\n\nTi auguro buona fortuna nella caccia. Possa tu tornare coperto di gloria.", nil, nil, 0xc62bac87, 0x3ab4cdf5, 0x6fee627e, nil, nil, "...mm" },
  [96107] = { "Piume per l'impennaggio", "Porta $N1 Piuma di Condor delle Pianure a Neza Grugnorosso a Rog'mar.", "Una cacciatrice consuma nella sua vita più frecce di quante stelle ci siano nel cielo.\n\nPersonalmente, le mie le faccio a mano. Mi fido solo del mio lavoro.\n\nLe piume ruvide dei condor qui vicino sono ottime per l'impennaggio. Mi aiuteresti raccogliendone qualcuna?", nil, nil, 0x0c7d04b3, 0xbed7ffa3, 0x61c3d52b, nil, nil, "...mm" },
  [96108] = { "Punte avvelenate", "Porta 4 campioni di Veleno di Vipera della Radura a Neza Grugnorosso a Rog'mar.", "Le frecce sono sempre essenziali, ma a volte serve qualcosa di più potente per abbattere la preda.\n\nÈ qui che entrano in gioco i rivestimenti velenosi. Rovinano la carne, ma se hai bisogno che qualcosa muoia, fanno il loro lavoro.\n\nI veleni si possono preparare oppure, se hai coraggio, raccogliere. Mi sembri più il secondo tipo.\n\nLe vipere vicino alle pozze a sud producono un veleno potente. Se ti ho giudicato bene, credo che potresti raccoglierne un po'.", nil, nil, 0xeb84f778, 0xd6ba3ab9, 0x61324629, nil, nil, "...mm" },
  [96109] = { "La faretra di un cacciatore", "Raccogli 6 Pelle di Leone Pregiata per Neza Grugnorosso a Rog'mar.", "Importante quanto le armi di un cacciatore è la sua faretra. Una buona faretra contiene molte frecce senza essere così grande da rallentare chi la indossa. Deve essere resistente e aderire bene al corpo.\n\nQui intorno non c'è materiale migliore per una faretra delle pelli di leone. Sono già adatte alla vita di un cacciatore nelle pianure.\n\nI leoni si radunano su una collina a sud. Puoi vederla da qui. Per favore, portami le loro pelli.", nil, nil, 0x800fa039, 0x11152be0, 0xbfa6c331, nil, nil, "...mm" },
  [96125] = { "Bisognoso di soccorso", "Trova Dunston Willis da qualche parte tra gli ogre a Bolder'ok.", "Ora che le pelli di leone sono state raccolte e i bracconieri orchi sfoltiti, posso finalmente prendermi una pausa.\n\nO meglio, è quello che direi se l'uomo che doveva darmi il cambio non fosse scomparso.\n\nDunston Willis, esploratore straordinario, è andato a indagare sull'insediamento degli ogre a nord pochi giorni fa. Aveva detto che avrebbe preso il mio posto al suo ritorno.\n\nTrovalo. Se è vivo, riportalo qui. Se è appeso ai ganci da macellaio, portami una prova così che Demar possa mandarmi qualcun altro.", nil, "Vieni dal Presidio di Terral? Eh, scommetto che Cornelius non è troppo contento di me in questo momento.", 0x95a013a5, 0x8efb13cb, 0xf7e0d354, nil, 0xba46babc, "...m." },
  [96126] = { "Il prigioniero di un ogre", "Trova Gronok il Macellaio, uccidilo e porta a Dunston la chiave delle sue catene.", "Non so come tu sia entrat<o/a> qui, ma ti prego, ascoltami.\n\nCome sai, faccio la guardia a Forte Farholde.\n\nDurante una ronda sono stato teso in un'imboscata da una banda di questi bruti e fatto prigioniero. Ora sono costretto a combattere nell'arena per il loro divertimento.\n\nMi resta poca forza. Se devo fuggire, è ora o mai più.\n\nIl mio carceriere è un ogre che chiamano \"Gronok il Macellaio\". Ha la chiave delle mie catene. Mi porterai quella chiave e mi aiuterai a uscire di qui?", "Meno male che qualcuno mi ha finalmente trovato. Non so quanti altri giorni avrei potuto sopravvivere.", "Hai la chiave! Eccellente! Ti sono infinitamente grato, {name}.\n\nOra, andiamo via di qui.", 0xa55362d4, 0x09aa0a47, 0x0a8f855f, 0x9fd3f589, 0x278fa4c6, "....." },
  [96130] = { nil, "Sconfiggi Chakuyak e riporta la sua pelliccia.", "Tra i lupi della prateria che cacciano sulle colline qui vicino c'è una lupa particolarmente aggressiva. Abbiamo preso a chiamarla Chakuyak. È diventata una minaccia per i viaggiatori che arrivano da lontano.\n\nSi aggira tra gli alberi a ovest del ⟦Stonebull Lake=Lago Toro di Pietra⟧, spostandosi da un boschetto all'altro.\n\nPoni fine a questa minaccia e portami la sua pelliccia, e canterò le tue lodi al capo. Ma fai attenzione: è pericolosa! Potresti incontrare altri cacciatori sulle sue tracce, e forse potreste lavorare in squadra.", "Hai trovato la grossa lupa?", "Togliere la vita a una creatura così bella è un evento triste, ma era necessario per la sicurezza della nostra gente. Mi assicurerò che la pelliccia non vada sprecata. Grazie.", 0x5e7713ac, 0x243d382f, 0x76d59655, 0xf8c970d1, 0x599fc946, "e...." },
  [96131] = { "Un Oldstone, ma un vecchio amico", "Porta il Ramo Debolmente Luminoso a Ketharas.", "Sono certa che hai incontrato quel vecchio brontolone che vive nella caverna a sud di qui?\n\nDevi portargli questo bastone insieme alla mia piuma. Capirà cosa significa. Oppure no! In ogni caso attirerà la sua attenzione.\n\nSarà anche un vecchio sasso, ma è affidabile. È uno dei pochi mortali a cui affiderei una questione grave come questa.\n\nPresto, terricolo! Temo che un'ombra stia calando su Hyjal, un'ombra che non possiamo vedere.", nil, nil, 0xef74a90f, 0xf0b626d8, 0x994fd83e, nil, nil, "...mm" },
  [96135] = { "Ascolta il mio richiamo", "Usa i totem distorti per porre fine al rituale dei verrospini.", "Bleah, solo a stare vicino a questi maledetti totem mi vengono i brividi... ma è un bene. Tutta questa corruzione distorta è proprio quello che ci serve per evocare gli elementali dei verrospini.\n\nVa' a ⟦Thousand Needles=Millepicchi⟧ e trova un punto adatto per le tue difese. Le pozze di vapore dovrebbero andar bene: sono ricche di fuoco, terra, acqua e aria insieme. Piazza questi totem e preparati a combattere. I ⟦Razormane=Chiomaguzza⟧ non prenderanno affatto bene la tua interferenza.", nil, nil, 0xb87aaede, 0x5eafbe6d, 0x93cfea2b, nil, nil, "...mm" },
  [96136] = { "Il richiamo dell'aria", "Trova ⟦Prate Cloudseer=Prate Scruta Nubi⟧ a ⟦Thousand Needles=Millepicchi⟧.", "Come avrai senz'altro sperimentato di persona, gli elementi di Azeroth sono diversi da quelli di Zephras. Una cosa è incanalare le forze della natura nei piani elementali, tutt'altra è farlo quaggiù, nel fango.\n\nPotrei concederti il tuo totem dell'aria, ma credo che ti gioverebbe di più incontrare chi addestra gli altri iniziati legati alla terra. Che ne dici, {name}?", nil, nil, 0x8f4acf86, 0x7a57cbe0, 0x94a7ee28, nil, nil, "...mm" },
  [96137] = { "Il pugnale di Ira", "Sconfiggi $N1 Young Black Ravager e $N2 Black Ravager, poi torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧ per saperne di più.", "Un piccolo pugnale appartenuto a Ira, guardaboschi autoproclamata, che proteggeva le foreste impedendo alle bestie che le abitavano di attaccare i viaggiatori.\n\nDato che lo spirito di Ira vaga ancora per i boschi, forse la sua questione in sospeso era sterminare i worg che continuano a mietere vittime in tutta la foresta.", nil, nil, 0x26c52f95, 0x8b815c85, 0x2af9a1e7, nil, nil, "...mm" },
  [96138] = { "L'arco di Merrick", "Sconfiggi $N1 Splinter Fist Warrior e $N2 Splinter Fist Taskmaster, poi torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧ per saperne di più.", "Un arco lasciato dallo spirito di Merrick Valor, celebre guardiano che andava fiero di tenere le strade al sicuro dai nemici invasori.\n\nDato che lo spirito di Merrick vaga ancora per le strade, forse la sua questione in sospeso era scacciare gli invasori vicino alla sua casa a ⟦Raven Hill=Collecorvo⟧. Forse sono gli ogre a sud del paese a turbare il suo spirito.", "Sì, di che si tratta?", "Merrick Valor, dici? Povero ragazzo, ha sempre voluto dimostrare il proprio valore. È stato un peccato quello che è successo a lui e alla sua famiglia.\n\nGrazie per averlo portato, {name}. Forse potrà far luce sulla storia di Collecorvo.", 0xfe4f08e4, 0xea183417, 0xd5097423, 0xb4a62c76, 0xc0e6c916, "....." },
  [96139] = { "La famiglia Valor", "Cerca a ⟦Raven Hill=Collecorvo⟧ qualunque cosa di interesse e torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧.", "In tempi bui come questi, è importante ricordare i nostri eroi quanto i nostri nemici. ⟦Darkshire=Borgoscuro⟧ non sarebbe ancora in piedi se non fosse per il coraggio di gente come la buona Lady Althea, o di chi perse la vita a ⟦Raven Hill=Collecorvo⟧.\n\nHai letto molto su ⟦Raven Hill=Collecorvo⟧? No, certo che no. La sua storia è stata cancellata insieme alla sua gente. La mia biblioteca, per quanto notevole, ha ben poco sull'argomento.\n\nSe per caso trovi qualcosa, apprezzerei se me lo portassi qui. Quella gente merita di essere ricordata.", "Hai trovato qualcosa? Non ci spero molto.", "Questo tomo sembra parlare della famiglia Valor. Credo di aver sentito parlare di alcuni di loro. Brava gente. Non so se meritino un intero libro tutto per loro.\n\nTi farò una copia del tomo. Se durante i tuoi viaggi trovi altro che li riguardi, sarà un piacere prenderlo in consegna.", 0x27a57039, 0x2c2db2c8, 0xb8e94707, 0xd0323cfc, 0xba858917, "....." },
  [96145] = { "Oltre ali e artigli", "Cerca Phoebe Piumalta al Sacrario di Aviana.", "Viaggiatore, fai attenzione! Anche se il Sacrario di Aviana si trova più avanti, la zona è ora rivendicata dalle arpie della tribù degli Alaverme.\n\nCome la mia famiglia, i Piumalta, sono una seguace di Aviana, ma gli Alaverme non sono altrettanto leali. Sono un pericolo per chiunque attraversi il loro territorio.\n\nSe riesci a superarli, mia cugina Phoebe Piumalta aiuta a proteggere il sacrario.", nil, nil, 0xedc8630e, 0x74a5d024, 0x040c78d4, nil, nil, "...mm" },
  [96204] = { "L'ira della Windshaper", "Accompagna Lumina Windsinger e aiutala a fuggire da ⟦Fenris Keep=Forte Fenris⟧.", "Ora che sono libera, farò pentire queste vili creature di aver mai posato gli occhi su una Windshaper.\n\nAndiamocene di qui, {class}.", nil, "Grazie ancora, {name}. Ho fatto conoscenza con Trevan qui, che, a quanto ho saputo, ti ha mandato sulle mie tracce.\n\nFinora, nei miei viaggi, ho sentito dire cose... poco caritatevoli sui paladini. Sono lieta che quelle insinuazioni siano del tutto infondate.\n\nTu e quelli come te avete un'amica tra i Windshaper.", 0x537b0fef, 0xdc69980b, 0x0c4dedf9, nil, 0x4b926baf, "...m." },
  [96209] = { "L'Antico, Orokai", "Cerca Orokai a ⟦Moonglade=Radaluna⟧.", "L'antico, Orokai, veglia appena fuori città. Portagli questo. Gli antichi sono meravigliosi e saggi. Purché questo ramo non sia stato separato dall'albero madre per troppo tempo, lui potrà \"parlare\" con esso per scoprire quali storie ha da raccontare.\n\nTrovi Orokai a sud-ovest della città, non troppo lontano.", nil, nil, 0x91a08c73, 0x2a64e9a6, 0xbbf33ee7, nil, nil, "...mm" },
  [96222] = { nil, "Porta il ⟦Maraudine Key Fragment=Frammento della Chiave di Maraudon⟧ a Umarak, a ⟦Desolace=Desolanda⟧.", "Mentre la guerra infuria in tutta la regione, i centauri ⟦Maraudine=Maraudon⟧ restano incontrastati nella ⟦Valley of Spears=Valle delle Lance⟧. Temo che col tempo diventino spietati e fomentino altri disordini, se gli altri clan continueranno a chiudere un occhio sulla loro presenza.\n\nKhan Hratha possiede un ⟦Maraudine Key Fragment=Frammento della Chiave di Maraudon⟧, e voglio averlo come arma di trattativa. Procurati il bocchino di un corno da guerra dai centauri del posto e usalo per sfidarlo in cima al picco più alto.\n\nPortami la chiave e avrò una proposta per te.", nil, nil, 0xa9d55f09, 0xffb7769a, 0x95b5e8c9, nil, nil, "e..mm" },
  [96241] = { "Parliamo di tossine, mon", "Usa l'⟦Toxin Extractor=Estrattore di Tossine⟧ per raccogliere $N1 Gloomrise Toxin Sample dai Gnawed Corpse dell'⟦Gloomrise=Altura Tetra⟧.", "Succede qualcosa di strano laggiù all'⟦Gloomrise=Altura Tetra⟧. Il vecchio Mazu'kon sente parlare un sacco di queste brutte bestiacce nuove che zampettano dappertutto là intorno.\n\nC'è chi dice che quegli insetti schifosi hanno un veleno con proprietà uniche, e questo mi fa venire curiosità. Prendi il mio estrattore. Usalo sui cadaveri sparsi per quel posto per raccogliere il veleno. Fallo, e io sarò in debito con te, mon.", "Hai preso quello che mi serve?", "Eh... quando ho detto proprietà uniche, non scherzavo, amico! Tu non sembri messo peggio, quindi va tutto bene.\n\nGrazie per aiuto, {class}. Molto apprezzato.", 0xb964176e, 0x8fd016de, 0x40a8707c, 0x7fd48cd6, 0x5f6ef15d, "....." },
  [96243] = { "Il richiamo della terra", "Trova Teo Hammerstorm a Dun Morogh.", "È ora che tu dia ascolto alla terra, <valoroso/valorosa> <Sciamano/Sciamana>. Gli elementi già ti pizzicano la pelle, ma una volta che avrai parlato con la pietra, il suolo stesso si farà saldo sotto i tuoi piedi... e nella tua anima.\n\nCerca Teo Hammerstorm nella ⟦Coldridge Valley=Valle Crestafredda⟧. Lo troverai dentro ⟦Anvilmar=Forgiamara⟧, una roccaforte forgiata con martello, fuoco e volontà.", nil, nil, 0xe316c17f, 0xf8e81384, 0x13c0eb8d, nil, nil, "...mm" },
  [96246] = { "Borselli degli Zannanera", nil, nil, nil, nil, 0xe558c49d, nil, nil, nil, nil, ".mmmm" },
  [96252] = { "Tesori ossidati", "Raccogli $N1 Braccialetto Ossidato di Piumalta dai nidi delle arpie Alaverme.", "{class}, vorrei chiederti un favore. Uno profondamente personale.\n\nQuando hanno teso un'imboscata e ucciso le mie sorelle, gli Alaverme hanno preso i loro gioielli, rivendicando questi tesori come trofei di battaglia. Peggio ancora, hanno nascosto i nostri tesori nei loro nidi con i loro piccoli non ancora nati: un'ulteriore prova della loro depravazione.\n\nTi prego di raccogliere i tesori delle mie sorelle cadute. Evita di danneggiare le uova non schiuse, se puoi, ma non perderò il sonno per le uova rotte dei nostri nemici.", nil, nil, 0x45dbdc27, 0x0b7a4293, 0xc6413990, nil, nil, "...mm" },
  [96255] = { "Midollo Amalgamato", "Uccidi la Melma Risvegliata della Vilcenere.", "<Qualcosa si dimena in modo sinistro dentro il mucchio di ossa, mentre della melma verde cola da sotto le ossa appena aggiunte.>", nil, nil, 0xa84078ba, 0xe1a19978, 0xe70d9892, nil, nil, "...mm" },
  [96259] = { "In difesa dei morti", "Uccidi $N1 Gloomrise Hatchling e $N2 Gloomrise Soldier.", "C'è un antico luogo di sepoltura tauren nel posto chiamato ⟦Gloomrise=Altura Tetra⟧, appena a nord-ovest di questo accampamento. Di recente è stato infestato da una covata di ragni particolarmente feroci. Questi ragni non sono solo una minaccia per la gente di Mulgore: stanno anche danneggiando un luogo che la maggior parte dei tauren considera sacro.\n\nMi faresti un grande servizio se andassi all'⟦Gloomrise=Altura Tetra⟧ e mettessi fine a questa infestazione. Gli antenati ti sorrideranno di certo, se ci riuscirai.", nil, "Grazie per il servizio reso alla gente di questa terra. Potrebbe volerci del tempo per eliminare completamente l'infestazione, ma i tuoi sforzi hanno creato un punto d'appoggio stabile da sfruttare contro queste vili creature.", 0x554fb829, 0xfedbb124, 0x55e7bece, nil, 0x8db1dcb9, "...m." },
  [96260] = { "Più forte dell'acciaio", "Raccogli $N1 ⟦Crystalline Silk=Seta Cristallina⟧ dai Gloomrise Spinner.", "Hai sentito cos'è successo al luogo di sepoltura dell'⟦Gloomrise=Altura Tetra⟧? Ragni giganti, che si dice abbiano un veleno così potente da risvegliare i morti, si sono diffusi come un incendio. Brutta faccenda, se vuoi il mio parere.\n\nUno degli esploratori mandati a indagare è tornato mezzo morto e coperto da una seta di ragno cristallina incredibilmente resistente. Ne ho raccolta quanta ho potuto, ma mi servirebbero davvero altri campioni di questa seta per studiarla ancora.\n\nPortami altra seta cristallina e ti ricompenserò.", "Le proprietà straordinarie di questa seta potrebbero servire a creare stoffa leggera e resistente, con notevoli proprietà difensive. Non vedo l'ora di sperimentare con altra.", "Sono campioni eccellenti, più che sufficienti per le mie necessità.\n\nTieni, prendi questo. Ho creato un mantello piuttosto unico con una trama filata dal piccolo campione di seta che già possedevo. Spero che lo troverai utile nei tuoi viaggi.\n\nChe Madre Terra vegli su di te, {class}.", 0x9eb7d49a, 0x87e2b5d5, 0x7ddec3da, 0xa4be7bfc, 0xadab23d3, "....." },
  [96261] = { "La madre della covata", "Uccidi Broodmother Valraxx all'⟦Gloomrise=Altura Tetra⟧.", "Come accade spesso con infestazioni come quella che affrontiamo all'⟦Gloomrise=Altura Tetra⟧, è una sola potente matriarca a causare la rapida diffusione di una popolazione ostile di ragni.\n\nSe vogliamo scacciare queste bestie per sempre, dovremo trovare la capostipite e farla finita con lei. Quando andrai all'⟦Gloomrise=Altura Tetra⟧, cerca la madre della covata e distruggila. Ti consiglio di portare degli alleati e di essere <pronto/pronta> a tutto. Questi non sembrano ragni comuni.", nil, "Morti rianimati? La madre della nidiata in una forma da elfa della notte? Sono rivelazioni inquietanti. Ci si chiede cosa significhi tutto questo... temo che sia un pensiero per un altro momento.\n\nGrazie, {name}. Hai reso un grande servizio al Circolo della Terra e alla gente di Mulgore.", 0xcdf04d8e, 0x37e65943, 0x0eed8922, nil, 0xb789e104, "...m." },
  [96262] = { "Pigne Spinose", "Raccogli $N1 Pigna Spinosa sotto gli alberi sani.", "Conosco queste colline da quando ero un pulcino. Se c'è una cosa che so, è che le pigne possono risolvere molti problemi.\n\nProbabilmente non te lo aspettavi, eh?\n\n<Il corvo ti fa l'occhiolino con aria cospiratoria.>\n\nVai a prenderne un po': fa parte di un piccolo piano che sto covando. Ti prometto che ne varrà la pena.\n\nDovresti trovarle sotto qualsiasi albero sano o vivo qui vicino. Stai lontano da quelli corrotti, però: quelle pigne non servono a niente!", nil, nil, 0xae528202, 0xeef22f1d, 0x1af91b33, nil, nil, "...mm" },
  [96264] = { "Aiuto elementale", "Sconfiggi ⟦Charlga Razorflank=Charlga Fiancospino⟧ nelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ e raccogli informazioni sui piani dei verrospini.", "Dunque adesso sei <uno/una> <sciamano/sciamana> pezzo grosso, eh? Hai padroneggiato gli elementi e vuoi metterli a buon uso? Credo di avere proprio quel che fa per te.\n\nSe vuoi il rispetto degli elementi, devi ripagare i tuoi debiti con loro. Loro aiutano te, tu aiuti loro. E proprio ora hanno bisogno di tutto l'aiuto possibile contro chi vorrebbe abusare del loro potere.\n\nLa terra brontola, {name}. Parla di verrospini che si radunano per un rituale di terribile potere. Dobbiamo andare a indagare nelle loro gallerie e scoprire cosa stanno combinando. Riportami qualunque cosa trovi.", nil, nil, 0x3a904965, 0xd3648ee8, 0x7dfb9fdc, nil, nil, "...mm" },
  [96265] = { "Il segreto degli Eremi Profondi", "Porta la Gemma Corrotta a Thera Soffiavespro a ⟦Winterspring=Fontefredda⟧.", "<I frammenti corrotti si fondono in una gemma ribollente di potere contaminato. I Guardiani vorranno vederla.>", nil, nil, 0xe4926094, 0x968417d5, 0x0c2746a5, nil, nil, "...mm" },
  [96294] = { "Una verità più oscura", "Porta la lettera che hai recuperato da Broodmother Valraxx a ⟦Muln Earthfury=Muln Terra Furiosa⟧, all'⟦Skywatcher Plateau=Altopiano dei Vegliacieli⟧.", "<La madre della covata che hai appena ucciso non è affatto un ragno, ma un druido elfo della notte che aveva assunto una distorta forma animale. Mille domande ti affollano la mente sulla natura, e sullo scopo, dei ragni dell'⟦Gloomrise=Altura Tetra⟧.\n\nNoti un biglietto che spunta dalle pieghe della veste dell'elfo morto. Forse questo documento potrà rispondere ad alcune delle domande che ti riempiono la testa.>", "Cos'è questo?", "Questo è... molto inquietante. Perché mai un druido dovrebbe essere dietro a una nidiata di ragni pericolosi? Chi o cosa sono questo «Re Selvatico» e questo «Patto» a cui si fa riferimento nella lettera?\n\nMi consulterò con i druidi del ⟦Cenarion Circle=Circolo Cenariano⟧. Forse ne sapranno di più.\n\nGrazie ancora per il tuo aiuto. Per quanto inquietante sia questa informazione, riposeremo più tranquilli sapendo che chi controllava queste vili creature è stato distrutto.", 0xceb16734, 0xff9e4493, 0x8d307e49, 0x1eb006e5, 0xc61ac103, "....." },
  [96296] = { "Corruzione fetida", "Trova e rimuovi $N1 Nodo Corrotto dagli alberi vicini.", "<Appena ti avvicini al nodulo pulsante, questo cade dall'albero, lasciando scoperta una linfa verde che trasuda. Sembra che l'albero abbia una corruzione dentro la corteccia che si è diffusa in profondità, ma l'albero non è ancora morto.\n\nGuardandoti intorno è chiaro che si è diffusa ad alcuni degli alberi circostanti, ma non tutti soffrono dello stesso livello di corruzione.\n\nForse non è troppo tardi per salvare gli alberi infetti nelle vicinanze.\n\nDi certo i Piumalta ti sarebbero grati se rimuovessi quanti più nodi corrotti riesci a trovare.>", nil, nil, 0x15581946, 0x33d2f8f5, 0xec9247aa, nil, nil, "...mm" },
  [96301] = { "Lavaggio a getto", "Entra nel ⟦Well of Eternity=Pozzo dell'Eternità⟧ e osserva i suoi effetti sul Cuore Gocciolante Veleno.", "Con in mano il cuore velenoso e tossico della chimera Ghansurok, immergiti nelle antiche acque del ⟦Well of Eternity=Pozzo dell'Eternità⟧.\n\nOsserva attentamente come le acque reagiscono alla corruzione, come la natura ricorda ciò che la corruzione sistemica ha cercato di disfare.\n\nPortami indietro l'organo e insieme leggeremo i segni che porta, e scopriremo se l'equilibrio può ancora essere ristabilito... o se la ferita è troppo profonda.", nil, nil, 0x1a1675e0, 0xe2ca219e, 0xdce1a970, nil, nil, "...mm" },
  [96302] = { "Arci-assoluzione", "Prendi l'incenso di Marn e lascia che il fumo protegga l'aria attorno ai resti di Archimonde.", "Ho compattato questa resina potente e pungente. Prendi questo incenso preparato e mettiti davanti ai resti caduti del Profanatore.\n\nPronuncia l'incantesimo mentre il fumo si leva, non per scacciare ciò che resta, ma per rasserenare lo spirito. Il suo aspetto porta ancora il ricordo del terrore e ancora oggi suscita paura in chi si attarda troppo.\n\nLascia che il fumo porti calma e determinazione, proteggendo la mente dal terrore, così che chi cammina in questo luogo possa ricordare la vittoria, non l'orrore.", nil, nil, 0x0b0d69f2, 0x49ecfbef, 0xc6e43f87, nil, nil, "...mm" },
  [96303] = { "Nebbia della memoria", "Usa il Ramo Incantato per liberare $N1 fuochi fatui attorno a Nordrassil.", "{name}, gli spiriti ancestrali richiamati a Hyjal durante la grande battaglia non sono andati tutti perduti. Alcuni indugiano ancora, attratti da Nordrassil dopo il grande sacrificio. Questi spiriti fatui sono rimasti nella chioma di radici che pende sul pozzo, intrappolati in uno stato di purgatorio tra questo mondo e il successivo.\n\nUsa questo ramo incantato per portare pace a questi spiriti, unendo i loro ricordi all'eternità.\n\nNon devi liberarli tutti tu. Recupera la volontà di cinque e riporta il ramo a noi.", nil, nil, 0xe89ceca4, 0xb260d358, 0x895d05d4, nil, nil, "...mm" },
  [96321] = { "Il dio morente", "Trova qualcuno sul ⟦Mount Hyjal=Monte Hyjal⟧ che possa essere interessato al Bastone Debolmente Luminoso.", "Io... non ho molto tempo, mortale. Devi prendere questo bastone, un ramo dell'albero del mondo... corrotto... sbagliato. L'ho portato qui...\n\nGli Dei Selvatici... devono saperlo. Portalo a lei. Il... corvo...\n\n<Il Dio Selvatico morente si fa immobile e i suoi occhi fissano il vuoto. Quel poco che resta della sua forma corporea sembra frantumarsi e disperdersi. A terra c'è un ramo debolmente luminoso, con un malsano cristallo verde fissato alla sommità.>", nil, nil, 0x0fa378ff, 0x64106ec2, 0x3450f223, nil, nil, "...mm" },
  [96322] = { "Una vendetta ora amara", "Parla con Felflick.", "Sai, per essere un mortale sono impressionato da quanto facilmente segui gli ordini.\n\nSei entrato lì dentro e hai ucciso tutta quella gente senza battere ciglio!\n\nAhhhh... ma ora è il momento della TUA parte dell'accordo, \"amico\". Ti ho aiutato a smantellare lo stupido Regno delle Ceneri, a eliminare i loro capi e a paralizzare le loro operazioni qui.\n\nPenso di essermi guadagnato la mia libertà.\n\n<Gli occhi di Felflick brillano d'attesa.>", nil, nil, 0x1a3bcf28, 0xbff845e3, 0x1e95b85a, nil, nil, "...mm" },
  [96332] = { "Una piccola rivalsa", "Entra nella Prigione di Alcaz e uccidi $N1 Soldato Strashaz e $N2 Incantatrice Strashaz, poi porta la testa della Signora delle Maree Ca'zass al sergente Ulka.", "Una seconda ondata di Naga si stava avvicinando alla fortezza mentre ci ritiravamo. Sospetto che la battaglia infuri ancora al suo interno.\n\nNoi Kor'kron ripaghiamo sangue con sangue. Se stai comunque andando là dentro, voglio che tu uccida ogni Naga che vedi. Ho visto anche un'incantatrice tra loro e puoi scommettere che era la loro capa. Portami la sua testa.\n\nOggi abbiamo perso molti bravi orchi e non mi darò pace sapendo che non abbiamo reso quanto ricevuto.", nil, nil, 0x1a1e0f10, 0x2a538404, 0x9957f7af, nil, nil, "...mm" },
  [96334] = { "Bandane Rosso Sangue", "Entra nella Prigione di Alcaz e raccogli $N1 Bandana Rosso Sangue dalle guardie umane.", "La maggior parte degli umani che abbiamo combattuto indossava bandane rosso sangue. Mi pare di ricordare di aver sentito parlare di un'organizzazione criminale attiva nei Regni Orientali conosciuta come \"la ⟦Defias Brotherhood=Fratellanza dei Defias⟧\", nota per le sue maschere rosse. Perché siano attivi qui a Kalimdor non lo so, ma uccidi chiunque incroci il tuo cammino e porta le loro maschere a Eitrigg a Orgrimmar.\n\nLui saprà stabilire se sono davvero maschere dei Defias.", nil, nil, 0xc5237fd4, 0x5ef8533e, 0x207c5ebf, nil, nil, "...mm" },
  [96335] = { "L'uomo in catene di ferro", "Recupera la ⟦Shackle Key=Chiave delle Catene⟧ di Alcaz dall'Interrogatore nella Prigione di Alcaz.", "Wow! È stato impressionante. Il modo in cui hai abbattuto quel drago è stato davvero qualcosa!\n\nGià che sei qui... pensi di poter aiutarmi a liberarmi da questa palla e catena?\n\nSe non è già fuggito o non è stato ucciso, il torturatore che chiamano \"l'Interrogatore\" dovrebbe avere le chiavi di queste catene. Prendi la chiave da quel sadico e portamela.\n\nTi prometto che, se lo fai, ne varrà la pena.", "Che ne dici di smetterla con le chiacchiere e di concentrarci sul tirarmi fuori di qui!", "Che bello togliersi quelle catene. Non ricordo nemmeno da quanto tempo ero legato. Ora mi servono solo una locanda, una doccia, una rasatura... e la sensazione di un completo.\n\nForse anche un taglio di capelli. Mi sento un po' trasandato.", 0x13152ee6, 0xff532844, 0xe7e955b8, 0x96c9175c, 0x74aa1ed0, "....." },
  [96337] = { "Più prezioso dell'oro", "Usa il biglietto lasciato da Mason Connery per trovare il suo tesoro nascosto.", "Ti avevo detto che avrei fatto in modo che liberarmi ne valesse la pena. Non ho oro per te, ma ho qualcosa di meglio.\n\nPrendi questo. Ti aiuterà a trovare un tesoro più prezioso dell'oro. Fanne ciò che vuoi, ma se qualcuno ti chiede dove l'hai preso, di' che la persona che te l'ha dato è morta.\n\nDi' che è stato vaporizzato dal fuoco del drago... spazzato via in mare.", "<Trovi un piccolo scrigno d'oro sepolto in una buca poco profonda nel terreno. Qualunque cosa contenga, non è grande.>", "<Trovi uno scrigno pieno di documenti, mappe e altri materiali. Vedi gli stemmi di ⟦Stormwind=Roccavento⟧, Gilneas, Lordaeron e altri sigilli dall'aria ufficiale che non conosci.\n\nLa maggior parte del contenuto di questi documenti per te non ha molto senso. Vedi una mappa di un luogo chiamato Kalidar, un dipinto sfocato di quella che sembra un'ogre femmina e un rapporto di rilevamento parzialmente bruciato intitolato «A. Crater; Kalimdor».\n\nNon ha molto senso per te, ma potrebbero valere qualcosa per qualcuno, forse?>", 0xe7c0a763, 0xaf347d6f, 0x50921a6d, 0x3d6b99f3, 0x2537ff44, "....." },
  [96339] = { "Ricompensa dell'eredità: ⟦Replica Ironforge Air Rifle=Replica del Fucile ad Aria di Forgiardente⟧", nil, nil, nil, nil, 0x049ac689, nil, nil, nil, nil, ".mmmm" },
  [96369] = { "Brutte notizie per Folkar", "Torna a riferire al comandante Folkar.", "<Il re è morto, ucciso in un tentativo di fuga poco prima dell'attacco dei Naga. Molti Kor'kron sono morti per apprendere questa notizia, ma questa conoscenza potrebbe scuotere l'⟦Alliance=Alleanza⟧ fin nelle fondamenta. Devi tornare dal comandante Folkar e riferirgli ciò che hai scoperto il più in fretta possibile.>", nil, nil, 0x41f46ebc, 0xb6344476, 0x5e6514d9, nil, nil, "...mm" },
  [96376] = { "Segreti di stato", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96377] = { "Segreti di stato", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96379] = { "Segreti di stato", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96381] = { "Un po' di lavoro sporco", "Entra nella Prigione di Alcaz e uccidi $N1 Soldato Strashaz e $N2 Incantatrice Strashaz, poi porta la testa della Signora delle Maree Ca'zass a Sully McCleary.", "Spiavo la riva di Alcaz con il mio fidato cannocchiale mentre tu eri via a origliare dama Marefiero. Penso che l'isola possa essere sotto attacco. Ho visto dei naga, tanti, che si lanciavano sulla riva.\n\nIl nemico del mio nemico non è certo mio amico quando si tratta di naga, quindi facciamo un favore al mondo ed eliminiamone un po'. Ho anche avvistato quello che sembra il capo: un tipo incantatore che abbaiava ordini. Fai fuori anche lei, se puoi.", "Come procede il «lavoro sporco»?", "Lo so, lo so, questi serpenti marini viscidi puzzano più dentro che fuori. Pensa solo che il mondo è un pochino migliore con qualche naga in meno che striscia in giro.", 0xc062c89e, 0x3abd7349, 0x28a62023, 0xe2ba93a6, 0x72a5760d, "....." },
  [96383] = { "Ricompensa dell'eredità: ⟦Spectral Bear Cub=Cucciolo d'Orso Spettrale⟧", nil, nil, nil, nil, 0x282c1e94, nil, nil, nil, nil, ".mmmm" },
  [96390] = { "Stroncarli sul nascere", "Uccidi $N1 Dark Iron Spy a Dun Morogh.", "Delle spie ⟦Dark Iron=Ferroscuro⟧ si sono infiltrate a Dun Morogh. A che scopo non posso dirlo con certezza, ma è un problema che dobbiamo stroncare sul nascere, prima che cresca.\n\nDirigiti a est, verso il ⟦Ironband's Compound=Presidio di Ferrocollo⟧, e uccidi le spie ⟦Dark Iron=Ferroscuro⟧ che trovi lì.", "Com'è andata? Gliene hai date quante ne meritavano?", "Questi Ferroscuro saranno anche nostri cugini, ma non sono famiglia, questo è certo. Non verso lacrime per le disgrazie che capitano a quelli che si allontanano troppo da quella loro montagna maledetta.\n\nSperiamo che basti a dissuaderli da altre incursioni in queste terre.", 0x5f38218b, 0x10fb22fa, 0x9db0e0ef, 0x68b3128a, 0xd5731f3e, "....." },
  [96391] = { "Una mappa dei sotterranei", "Consegna la ⟦Dark Iron Map=Mappa dei Ferroscuro⟧ al veggente della terra Farsen, a Dun Morogh.", "La mappa che hai in mano sembra mostrare una complessa rete di gallerie e strade sotterranee che convergono tutte in un punto proprio sotto ⟦Ironforge=Forgiardente⟧.\n\nNon puoi sapere con certezza cosa dicano le rune, scritte nella brutta e spigolosa lingua runica dei nani ⟦Dark Iron=Ferroscuro⟧, ma puoi intuire lo scopo di queste gallerie. Mentre leggi la mappa, una folata di vento ti investe e senti, debole, una voce nanica portata dal vento. Il veggente della terra Farsen deve vederla.", "Oh, e questo cos'è?", "A giudicare da questa mappa, sembra proprio che questi Ferroscuro stiano preparando una specie di incursione nelle cripte sotto ⟦Ironforge=Forgiardente⟧. La banda che hai sgominato a est dev'essere una forza di ricognizione.\n\nGrazie per avermela portata. Se ci sbrighiamo, forse riusciremo a precederli, qualunque sia il loro obiettivo laggiù.", 0x9d9cce92, 0x0559f95b, 0x9898e535, 0x52844eeb, 0x1c2fe859, "....." },
  [96392] = { "Lo sguardo di Farsen", "Parla con il veggente della terra Farsen e chiedigli di prestarti la sua vista lontana per osservare la minaccia ⟦Dark Iron=Ferroscuro⟧.", "Salute a te, amico. Mi chiamo Farsen, veggente della terra, e sono a Dun Morogh in visita dal ⟦Aerie Peak=Picco dell'Aquila⟧. Mentre viaggiavo, non ho potuto fare a meno di notare che abbiamo, be'... un certo problema di nani Ferroscuro.\n\nSe hai un momento, posso mostrarti cosa intendo. Ho un pizzico di magia che dovrebbe fare al caso nostro.", "La vista lontana può mostrarti molte cose, anche cose che preferiresti non vedere.", "Allora, ora capisci, {class}? Sono fitti come scarafaggi, e sono solo quelli che vediamo dal cielo.\n\nMi sembri abbastanza robust<o/a>. Che ne dici di un po' di violenza?", 0x9243cd15, 0x987a4089, 0xce20450c, 0x19a9ef2c, 0x478676d1, "....." },
  [96393] = { "Incursione nella Vecchia ⟦Ironforge=Forgiardente⟧", "Entra nella Hall of Thanes sotto la Vecchia ⟦Ironforge=Forgiardente⟧ e prendi la testa di Durgen Dirgehammer.", "Raduna qualche alleato e scendi nelle caverne sotto la Vecchia ⟦Ironforge=Forgiardente⟧. Entra nella Hall of Thanes e spingiti fino alle cripte inferiori.\n\nIl mio ⟦Dark Iron=Ferroscuro⟧ è un po' arrugginito, ma riesco a decifrare un nome: un certo Durgen Dirgehammer. Probabilmente è lui il comandante. Prendi la sua testa e consegnala a re Magni Barbabronzea.\n\nAh, e quando lo fai, digli che il suo vecchio amico Farsen gli manda i suoi saluti!", "Di che cosa hai bisogno, <cittadino/cittadina>?", "Un'incursione ⟦Dark Iron=Ferroscuro⟧... proprio sotto i nostri piedi? Be', è un sollievo sapere che il comandante ⟦Dark Iron=Ferroscuro⟧ è stato eliminato.\n\nLe guardie entreranno a ripulire il resto della marmaglia. Faremo in modo che le brecce vengano sigillate e i livelli inferiori rinforzati, così che nessun'altra incursione sia possibile.\n\nGrazie per il tuo servizio a ⟦Ironforge=Forgiardente⟧, {class}. Accetta questo piccolo pegno della mia gratitudine. Ah, e se rivedi Farsen, quel vecchio Granmartello abbracciarocce, digli di venirmi a trovare come si deve.", 0x48866402, 0xe0bec594, 0xa08604c5, 0xa75dc075, 0x0fc00f59, "....." },
  [96394] = { "I morti senza pace", "Uccidi $N1 Enraged Apparition e $N2 Tormented Soul, e dai riposo allo spirito del thane ⟦Anvilmar=Forgiamara⟧.", "Qualcosa ha disturbato le tombe giù nella Hall of Thanes, e dal profondo delle cripte si sentono strani rumori. Gli spiriti dei morti hanno il sonno leggero, e qualunque cosa stia succedendo laggiù sembra averli spaventati.\n\nScendi laggiù e vedi cosa puoi fare per noi. Se qualche morto si è svegliato... be', rimettilo a dormire!", "Non ho tempo per ghoul e fantasmi. Ho un lavoro da fare quaggiù.", "Ah, bene, allora è fatta. Non posso permettere che gli altri custodi si rifiutino di entrare nella sala a fare il loro dovere per colpa di «fantasmi» e «morti arrabbiati», no?", 0x69066003, 0x6a43847e, 0xd9e1bd9c, 0x225e19e2, 0x1d4545a7, "....." },
  [96395] = { "Un antico rancore", "Dai riposo allo spirito di Faldrim ⟦Anvilmar=Forgiamara⟧, poi torna dal Ghostly Attendant nella Hall of Thanes.", "Il... thane... il mio potente... thane... ha... bisogno di... riposare.\n\nTi prego... aiutalo... aiutalo... a riposare...\n\nConsumato... da un... antico... rancore... Nessun... riposo...", "<La figura spettrale fissa il vuoto oltre di te. La sua bocca si muove, ma si sentono solo bassi rantoli indistinti.>", "Il mio... thane... riposa... sì... riposa.\n\nGrazie... a te...\n\nIo... riposo...", 0x372fadb2, 0xf47ad935, 0x22f3d060, 0x9e32e5af, 0x80ede96a, "....." },
  [96403] = { "Cimeli importanti", "Raccogli $N1 Dwarven Heirloom nella Hall of Thanes.", "Ehi, tu, <avventuriero/avventuriera>... mi servirebbe proprio il tuo aiuto.\n\nStavo sgattaiolando... ehm... «pattugliando» le cripte, quando una squadra di nani ⟦Dark Iron=Ferroscuro⟧ è sbucata dalle profondità a bordo di talpe meccaniche! Non so cosa siano venuti a fare, ma laggiù c'è un bottino inestimabile... ehm, o meglio... voglio dire, ci sono «importanti cimeli culturali»! Ti prego, recupera tutti i reperti di questo tipo che vedi e riportali qui.\n\nTi assicuro che tutto ciò che recupererai sarà catalogato e restituito al suo legittimo posto d'onore.", "<Thom si sfrega distrattamente le mani mentre ti guarda.>", "Ma guardati, coraggios<o/a> quanto intraprendente! Sono uno gnomo di parola, e la tua ricompensa è ben meritata!\n\nOra fammi dare un'occhiata al bottino... ehm, voglio dire... ai cimeli recuperati. Devo cominciare a valutarli... pardon, a «catalogarli», così da poterli rimettere al loro posto il prima possibile.", 0xdb5e0561, 0x7bf6ecf5, 0x1019355e, 0xb065081e, 0xd63d4304, "....." },
  [96408] = { "Un visitatore a Dun Morogh", "Ispeziona l'accampamento che domina la ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.", "Ieri notte uno dei nostri montanari ha avvistato un fuoco da campo su un pendio a est. Sembra piuttosto in alto, sopra la ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.\n\nProbabilmente non è niente, ma vorrei che andassi a dare un'occhiata a quell'accampamento. Se sono amici, nessun danno. Se non lo sono... be', sai cosa fare.", nil, "Salute, amico. Come va?", 0x7b3a9976, 0x89d2ded4, 0x1a6a0853, nil, 0x9c8725d7, "...m." },
  [96435] = { "Una fine appropriata", "Getta le ossa dello stregone nel mucchio di ossa vicino alle pozze di melma.", "<Felflick ridacchia con gioia mentre osserva le ossa insanguinate dei capi del Regno delle Ceneri.>\n\nOh, questo è semplicemente perfetto!\n\n<Felflick salta avanti e indietro nella sua gabbia, ridacchiando di continuo.>\n\nOra è il momento di dare a quegli stregoni la fine che meritano. C'è un enorme mucchio di ossa a ovest di qui, se segui la strada. Fidati, è impossibile non vederlo. È lì che finiscono tutti i loro esperimenti \"falliti\".\n\nÈ lì che voglio gettare i resti di questi sciocchi. Che tutto il mondo sappia che fallimenti sono!", nil, nil, 0x9ccc7a6b, 0x95eef7e8, 0x8836fb72, nil, nil, "...mm" },
  [96438] = { "Battaglia alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧", "Indaga sulla battaglia alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧ a ⟦Desolace=Desolanda⟧.", "{name}, ho bisogno del tuo aiuto. Uno dei nostri fratelli, passando per la Punta di Nigel a ⟦Desolace=Desolanda⟧, ha sentito dei dettagli su una battaglia avvenuta alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧. Si dice che una delle parti abbia portato in battaglia una potente magia sacra contro gli stregoni di lì. Sicuramente erano coinvolti dei seguaci della Luce.\n\nVorrei sapere di più su chi ha partecipato a questo scontro. Se uno dei nostri era coinvolto, o è caduto là... voglio saperlo.", nil, nil, 0x16f8ad12, 0x53828f2a, 0x947ec34f, nil, nil, "...mm" },
  [96449] = { "Il rifugio segreto di Aeonas", "Usa la vecchia barchetta al ⟦Menethil Harbor=Porto di Menethil⟧ per cercare Aeonas.", "Ora che ci penso, conosco un posto isolato molto a sud di qui. Qualcuno una volta mi ha detto che si chiama Approdo di Newman, anche se non chiedermi chi sia questo \"Newman\". Dovresti cominciare a cercare il vecchio Aeonas lì.\n\nPuoi usare la mia vecchia barchetta ormeggiata laggiù, subito dopo il molo più a nord. Non è granché, ma ti porterà lì più in fretta che a nuoto.\n\nSpero davvero che non gli sia successo niente. Starei più tranquillo se andassi a controllare il nostro amico.", nil, nil, 0xfec7166c, 0x2ce13332, 0x6224132b, nil, nil, "...mm" },
  [96476] = { "Alla ricerca di Aeonas", "Cerca tracce di Aeonas il Vendicato al ⟦Emerald Sanctuary=Santuario di Smeraldo⟧ a ⟦Felwood=Vilbosco⟧.", "Aeonas ha accennato a ⟦Felwood=Vilbosco⟧, quindi è possibile che sia lì. C'è un piccolo insediamento nella parte meridionale del bosco, noto come ⟦Emerald Sanctuary=Santuario di Smeraldo⟧. Ti consiglio di chiedere in giro per vedere se qualcuno l'ha visto.", nil, nil, 0xaf8071c4, 0xbac5a578, 0x8abc0364, nil, nil, "...mm" },
  [96494] = { "Si addensa la tempesta", "Trova il punto di rinforzo degli Spinanera all'ingresso della Sommità di Hyjal.", "Dopo aver esplorato il perimetro, ti sei dimostrat<o/a> abbastanza utile e affidabile da essere accolt<o/a> nel gruppo.\n\nSono qui in rappresentanza degli sforzi dell'IR:7 per ottenere informazioni cruciali importanti per l'⟦Alliance=Alleanza⟧. Non chiunque è a conoscenza di queste informazioni. Sii discreto.\n\nUn culto druidico noto come Patto di Spinanera ha messo radici nelle vicinanze, operando al servizio di qualcosa che chiamano il Re Selvatico.\n\nTrova il dominio di questo \"Re Selvatico\" e segnalo. Poi potremo riferire a ⟦Stormwind=Roccavento⟧ con certezza.", nil, nil, 0xe5c57e46, 0xc6ea4966, 0x5fca695e, nil, nil, "...mm" },
  [96529] = { "Un affare alla Shaw", "Porta le Informazioni sugli Spinanera al ⟦Master Mathias Shaw=Maestro Mathias Shaw⟧ a ⟦Stormwind=Roccavento⟧.", "Il tuo aiuto è stato fondamentale per i nostri sforzi di ricognizione. Porta queste informazioni al ⟦Master Mathias Shaw=Maestro Mathias Shaw⟧ a ⟦Stormwind=Roccavento⟧.\n\nRicorda, non devi parlare delle nostre attività qui, della mia presenza o del coinvolgimento dell'⟦SI:7=IR:7⟧ con nessun altro. Ho ancora molto da organizzare qui e dei piani da portare avanti.\n\nCi faremo sentire.", nil, nil, 0x00c54442, 0xbb26a5a5, 0x0b5db282, nil, nil, "...mm" },
  [96550] = { "Richiamo in battaglia", "Usa il Fodero Ricamato per parlare con il veterano di guerra e ascoltare la sua storia al belvedere della Selva Antica.", "Il vecchio fodero è decorato con motivi e segni intagliati. Corrisponde alla descrizione fatta dal veterano di guerra. Una vista spettacolare della terra sottostante è uno spettacolo mozzafiato.\n\nForse basta tenere il fodero in mano mentre ricordi le parole del veterano per richiamare lo spirito a questo ricordo.", nil, nil, 0xae620b44, 0x877f7c07, 0x98c24f9b, nil, nil, "...mm" },
  [96558] = { "Conforto del soldato", "Recupera la Scorta da Battaglia sepolta sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Sotto le pietre in frantumi di quella torre di guardia si trova un nascondiglio che abbiamo sepolto in fretta, quando il mondo iniziava a bruciare. Quel poco che abbiamo portato da Hyjal riposa ancora lì. Prendilo: te lo sei guadagnato.\n\nL'attrazione aumenta... la montagna non mi trattiene più come un tempo. Non so se ci parleremo ancora.\n\nGrazie a te, ricordo chi ero e chi eravamo. Vai con la mia gratitudine e lascia che questo spirito trovi finalmente pace.", nil, nil, 0xe607edf5, 0x69f605f5, 0xd6a6939e, nil, nil, "...mm" },
  [96559] = { "Lancio di rifornimenti", "Trova il Kit di Sopravvivenza del Pilota di Fenwick Mollascatto.", "Ogni pilota collaudatore gnomo sa che bisogna essere preparati al peggio quando si solcano i nostri grandi cieli!\n\nÈ per questo che non lasciamo mai l'hangar senza i nostri kit di sopravvivenza del pilota. Hanno un segnalatore ad auto-attivazione che trasmette la nostra posizione alla base non appena lo apri. Senza contare che sono pieni di altre utili provviste.\n\nSe riesci a trovare quello zaino ovunque sia caduto, aprilo subito e serviti pure del contenuto. Mi starai comunque facendo un favore!", nil, nil, 0xf9b68c03, 0xc4da7a46, 0xd7bbd2ea, nil, nil, "...mm" },
  [96561] = { "Ultimi desideri", "Trova lo stagno di pesca vicino alla segheria distrutta dell'⟦Alliance=Alleanza⟧ nella Culla della Tranquillità.", "<Spieghi la semplice pergamena.>\n\nAi miei Ribelli Scalmanati di ⟦Redridge=Crestarossa⟧,\n\nI taglialegna di qui dicono che i gulper in quello stagno abboccano come se facessero a gara a chi arriva prima all'esca. Pesce buono, ancor meglio da mangiare. Quando questa guerra sarà finita, ci spetta una gara di pesca tra amici.\n\nLe regole sono semplici: stiamo sull'isola al centro e peschiamo finché il sole non scivola dietro la vetta più alta di Hyjal.\n\nChi ne prende di più non deve sventrarli per la nostra cena!\n\n-- Tobin --", nil, nil, 0x4174693e, 0x4ad04d6d, 0x433b69ee, nil, nil, "...mm" },
  [96602] = { "Altra magia instabile", nil, nil, nil, nil, 0x21b0f176, nil, nil, nil, nil, ".mmmm" },
  [96603] = { "Magia instabile", "Porta $N1 Particella di Magia Instabile all'arcimago Celindra a Dalaran.", "L'arcimago Rhonin è attualmente all'estero a indagare su un'anomalia nel flusso della magia in tutta Azeroth. L'arcimago mi ha incaricato di richiedere l'aiuto di avventurieri forti come te per raccogliere importanti dati sul campo che lo aiutino.\n\nPrendi questo Incensiere Arcano. Finché la sua magia ti affligge, potrai estrarre granelli di magia instabile dai più abili incantatori e da altre entità singolarmente potenti che incontrerai. Portami i suddetti granelli e il Kirin Tor sarà in debito con te.", nil, nil, 0xd9f44e11, 0x5b11ae4f, 0x7d290c22, nil, nil, "...mm" },
  [96604] = { "La vita all'aria aperta", "Siediti vicino al ⟦Brakk's Basic Campfire=Fuoco da Campo Semplice di Brakk⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Lok-tar, {class}. Hai proprio l'aria dell'avventuriero, e questo è un bene. Il mondo ha bisogno di altre anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nIn questo mestiere, per avere successo, dovrai imparare a cavartela nelle terre selvagge. Non so quanto tu sia <bravo/brava> all'aperto, ma qualcosa probabilmente posso insegnartelo, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego io come si fa.", nil, "Ora che abbiamo imparato le basi, va' a imparare un mestiere dagli istruttori del villaggio qui vicino. Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xc9a7eaed, 0x1dfc83c1, nil, 0xeab943b1, "...m." },
  [96605] = { "La vita all'aria aperta", "Siediti vicino al ⟦Kaga's Basic Campfire=Fuoco da Campo Semplice di Kaga⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Avere le competenze necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x6d44875e, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96606] = { "La vita all'aria aperta", "Siediti vicino al ⟦Lyreena's Basic Campfire=Fuoco da Campo Semplice di Lyreena⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Possedere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xbbb8647e, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96607] = { "La vita all'aria aperta", "Siediti vicino al ⟦Eleanor's Basic Campfire=Fuoco da Campo Semplice di Eleanor⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x71b45cb3, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96608] = { "La vita all'aria aperta", "Siediti vicino al ⟦Eric's Basic Campfire=Fuoco da Campo Semplice di Eric⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x2837fcc0, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96609] = { "Il sapore di casa", "Porta $N1 bottiglie di Vino Scintillante di Lunargenta ad Arille Sguardazzurro nella città di Dalaran.", "Conosci il Vino Scintillante di Lunargenta? Ha un sapore delicato, del tutto unico dei vigneti di Cantoeterno, ed è l'unica cosa che mi manca davvero della mia terra natale.\n\nPurtroppo è estremamente difficile da trovare da questa parte della Porta Thalassiana.\n\nUn cliente mi ha portato una bottiglia che sosteneva di aver \"liberato\" agli elfi del sangue nel nord di Azshara. Se le tue avventure ti portano in quella regione e riesci a recuperare altre bottiglie per me, ricompenserei generosamente i tuoi sforzi.", nil, nil, 0x2177fad0, 0xe0add89f, 0x4eaf2dbf, nil, nil, "...mm" },
  [96616] = { "Erbe per i contusi e gli stanchi", "Raccogli $N1 Silfio di Hyjal.", "Può essere? I viaggiatori sono tornati a Hyjal!\n\nQuasi non ci credo! Forse con il tuo aiuto saremo finalmente liberi da questo posto. Con i resti del Flagello a est siamo stati soggetti a continue incursioni e molti sono stati vittime della loro corruzione.\n\nTi prego, {class}. Vorrei chiederti un favore. Nella valle a nord di qui cresce un'erba dai fiori blu che può alleviare i dolori dell'infezione. Raccogline un po' e portamela, così potrò aiutare i feriti.", nil, nil, 0xc834be5b, 0x8e03a19a, 0x4209f9b4, nil, nil, "...mm" },
  [96622] = { "Un riposo senza dolore", "Consegna l'Impiastro di Silfio di Hyjal a Enho e Maruke.", "Vorrei chiederti un ultimo favore finché ti ho qui, amico. Potresti consegnare l'impiastro che ho preparato a due miei compagni qui nell'accampamento?\n\nEnho è nella nostra infermeria a sinistra. È molto debole ma spero ancora che riuscirà a superare l'infezione. Gli ho dato del brodo col cucchiaio per cercare di aiutarlo a riprendere le forze.\n\nL'altra è Maruke.\n\n<Ortak china la testa in silenzio per un momento.>\n\nLa troverai a nord di qui, dove teniamo le poche cavalcature che ci restano.", nil, nil, 0xb9e4ceb9, 0xc848e3e9, 0x462893c6, nil, nil, "...mm" },
  [96626] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con Tomas a ⟦Goldshire=Borgodoro⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x48b91f09, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96627] = { "Vita da avventuriero", "Parla con Sam Sarsparilla nei pressi di ⟦Goldshire=Borgodoro⟧.", "{name}, finora hai dimostrato il tuo valore come protett<ore/rice>. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di un nuovo avventuriero lungo la strada, vicino a ⟦Goldshire=Borgodoro⟧. Va' a vedere che cosa sta facendo.", nil, "Grazie per esserti preoccupat<o/a> per me, {class}. Quel maresciallo si agita per niente.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x24f0776f, 0x24463491, nil, 0xeb1c22f1, "...m." },
  [96628] = { "Vita da avventuriero", "Consegna il ⟦Supply Bundle=Fagotto di Rifornimenti⟧ a ⟦Eric Brighthammer=Eric Martello Lucente⟧ nei pressi di Kharanos.", "Aspetta, {name}. Ho un'altra richiesta da farti, prima che tu affronti quella galleria.\n\nI miei montanari hanno segnalato un avventuriero comparso appena fuori Kharanos. Potresti consegnargli queste provviste?", "Sei qui per imparare ad accamparti nelle terre selvagge?", "Dici che vengono dai montanari? Sì, mi fanno comodo. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0xbfabdfa9, 0x1f02236b, 0xf7a7f9bd, 0x5f83030c, "....." },
  [96629] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con Gremlock Pilsnor a Kharanos per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xfb18b446, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96630] = { "Vita da avventuriero", "Porta il diario a ⟦Lyreena Duskblade=Lyreena Lama del Vespro⟧ nei pressi di Dolanaar.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nDiverse pagine parlano di campeggio. Sembra proprio... divertente.>", "Sei qui per imparare ad accamparti nelle terre selvagge?", "È il mio diario? Era da un po' che non lo trovavo più. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0xc5322669, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96634] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con Zarrin a Dolanaar per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xa03560df, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96638] = { "Vita da avventuriero", "Parla con ⟦Raan Wildwind=Raan Ventoteso⟧ nei pressi del ⟦Shen'dar Village=Villaggio di Shen'dar⟧.", "Sempre più avventurieri come te cercano gloria e fortuna lontano dalla sicurezza del ⟦Thendal Grove=Boschetto di Thendal⟧. Uno di loro si è accampato fuori dal ⟦Shen'dar Village=Villaggio di Shen'dar⟧, lungo la strada che dal ⟦Thendal Grove=Boschetto di Thendal⟧ porta a sud-ovest.\n\nCercalo e scopri che cosa puoi imparare da lui che ti sia utile nei tuoi viaggi.", nil, "Ben trovat<o/a>!", 0x1afc3318, 0x72c75d4e, 0x5990b6bd, nil, 0x47da9bb0, "...m." },
  [96646] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con ⟦Zerril Softbreeze=Zerril Brezza Leggera⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x8b592b5f, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96652] = { "Vita da avventuriero", "Porta il diario a Brakk nei pressi di ⟦Razor Hill=Tranciacolle⟧.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nDiverse pagine parlano di campeggio. Sembra proprio... divertente.>", "Sei qui per imparare ad accamparti nelle terre selvagge?", "È il mio diario? Era da un po' che non lo trovavo più. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x19108351, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96655] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con il cuoco Torka a ⟦Razor Hill=Tranciacolle⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon falò è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x4f2cbefa, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96656] = { "Vita da avventuriero", "Parla con Eleanor Shackleton nei pressi di Brill.", "{name}, finora ti sei <dimostrato/dimostrata> degn<o/a> di fiducia nelle tue imprese contro la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di una nuova avventuriera lungo la strada, vicino a Brill. Va' a vedere che cosa sta facendo.", nil, "Non ho niente a che fare con la ⟦Scarlet Crusade=Crociata Scarlatta⟧, se non si fosse capito. Sono solo un'avventuriera di passaggio, prima della mia prossima spedizione nelle terre selvagge.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x60140125, 0x7846cd95, nil, 0xbb601ab5, "...m." },
  [96658] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con William Pickman a Brill per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon falò è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xca2cf982, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96659] = { "Vita da avventuriero", "Consegna il ⟦Supply Bundle=Fagotto di Rifornimenti⟧ a Kaga Wildhoof nei pressi del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Aspetta, {name}. Ho un'altra richiesta da farti, prima che tu ci lasci.\n\nC'è un'avventuriera di nome Kaga Wildhoof che si è accampata appena fuori dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. In passato mi ha aiutato molto, e ora vedo l'occasione di ricambiarla. Potresti consegnarle queste provviste?", "Sei qui per imparare ad accamparti nelle terre selvagge?", "Ti manda il capo Vento Agile? Gliel'avevo detto, allora, che non volevo nessun compenso, ma a quanto pare non mi ha ascoltata. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x8ee06ce3, 0xc65676fe, 0xf7a7f9bd, 0x113825f8, "....." },
  [96661] = { "⟦Camping=Campeggio⟧ 101: Cucina", "Parla con ⟦Pyall Silentstride=Pyall Passo Silente⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon falò è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xbe1a3274, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96666] = { "Legami nella Tana", "Raggiungi il grado Amichevole nella reputazione con la Tana dei Pelledura.", "I Pelledura parlano ancora meglio di te, amico, ma c'è ancora altro da fare per te.\n\nAlza la mano contro i nostri nemici. Onora le nostre vie.\n\nOsserviamo da vicino, e poi avremo altro da dirti.", nil, nil, 0x1dd1aa09, 0xb3e8554e, 0x1872ff19, nil, nil, "...mm" },
  [96674] = { "Pecora smarrita", "Cattura e riporta $N1 Pecora Fuggita.", "<Gli occhi di Mirt si spalancano mentre ti avvicini.>\n\nWow, chi sei? Mia mamma ha detto che c'era una persona nuova qui. Ha detto che hai ucciso un sacco di Flagello e sei fortissimo! Hai mai combattuto un orso? *sussulto* UN DRAGO!? Io...\n\n<Mirt si guarda alle spalle, poi sembra imbarazzato.>\n\nForse... potresti aiutarmi? Dovevo badare alle pecore ma sono scappate mentre facevo draghi di fango. Sono dall'altra parte, LÀ. Non mi è permesso andarci. Mamma dice che potrebbero farmi male. Potresti andare a cercare le pecore?", nil, nil, 0xcd7a4e99, 0xeed2ec15, 0xd520500d, nil, nil, "...mm" },
  [96676] = { "Rompere il sigillo del Patto di Spinanera", "Porta l'Equipaggiamento dell'⟦Alliance=Alleanza⟧ a Johun \"Cazzotto\" Dillas a Hyjal.", "Allora, informatore, sei stat<o/a> promoss<o/a>.\n\nPorta questi ordini aggiornati a Johun al suo campo base a Hyjal. Qui dentro c'è dell'equipaggiamento aggiuntivo di cui avrà bisogno per le nostre operazioni sulla Sommità.\n\nIl tuo aiuto in queste faccende è fondamentale per la nostra strategia complessiva a Kalimdor, {name}. Non indugiare.\n\nSei congedat<o/a>.", nil, nil, 0x4428a3f9, 0xbfe6302f, 0xbc3d0e64, nil, nil, "...mm" },
  [96735] = { "Un brindisi!?", nil, nil, nil, nil, 0x0f38dabc, nil, nil, nil, nil, ".mmmm" },
  [96770] = { "La testa del santone", "Uccidi il ⟦Witch Doctor Zum'rah=Taumaturgo Zum'rah⟧ e porta la Testa di Zum'rah all'arcimago Lan'dalock a Dalaran.", "Esiste un santone troll di nome Zum'rah. Ho una storia con questo particolare troll e vorrei che tu lo uccidessi per me.\n\nVai alla roccaforte dei Sabbiafurente a ⟦Zul'Farrak=Zul'farrak⟧, nel profondo dei deserti di Tanaris. Trova Zum'rah all'interno e distruggilo. Portami la sua testa, intatta, e farò in modo che tu sia equamente compensat<o/a>.", "La negromanzia dei troll è un'arte insidiosa e solo i troll con un'indole particolarmente malata e perversa la praticano. Zum'rah non sa che non è l'unico in grado di rianimare i morti, e perdere la testa è solo l'inizio dei suoi guai.", "Grazie per il tuo servizio al Kirin Tor, {name}. Ecco la tua ricompensa.\n\n<Dopo averti consegnato la ricompensa, l'arcimago Lan'dalock solleva la testa mozzata del troll e comincia a parlarle.>\n\nTu e io ora faremo una lunga conversazione, Zum'rah. Temo che non ti piacerà.", 0x40b5f7a9, 0xb988bb33, 0xea4ddda7, 0x8591a910, 0x45e416a2, "....." },
  [96771] = { "La vendetta degli ⟦Highborne=Alti Nobili⟧", "Recati alla Roccaforte di Krol'dok e uccidi Zalfan Lunascura.", "Nella regione nota come Radure del Fiume a sud-est c'è un posto chiamato Roccaforte di Krol'dok. Un Alto Nobile di nome Zalfan Lunascura è stato visto lì in compagnia del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nPagherei bene se mi liberassi di questo cretino. Porta disonore alla fiera stirpe degli Alti Nobili frequentando fanatici e usando conoscenze arcane rubate al loro servizio. Ne restiamo abbastanza pochi senza che vermi come lui infanghino il nostro buon nome.", nil, "Grazie, {class}. Mi hai fatto un grande favore e hai liberato il mondo da un cane traditore.", 0x9b77b441, 0x0210fb3d, 0x59c6ab25, nil, 0x9ca78a92, "...m." },
  [96772] = { "Il diario del drago", "Recupera il Diario di Zarla dalle profondità della Prigione di Alcaz.", "Timear e io abbiamo scrutato l'area di Kalimdor nota come ⟦Alcaz Island=Isola di Alcaz⟧ e abbiamo quasi confermato la presenza di un potente utilizzatore di magia. La maga in questione ha dissolto le nostre sonde, ma prima di farlo ho colto l'immagine di un tomo di qualche tipo. Credo fosse un diario, scritto in un'antica scrittura draconica.\n\nNon so cosa ci sia in quel libro, ma vorrei studiarlo. Vogliamo che tu vada nella prigione nascosta sotto l'⟦Alcaz Island=Isola di Alcaz⟧ e recuperi quel libro per noi.", "Hai recuperato il diario?", "Quindi il mago che avevamo individuato era in realtà un drago nero sotto mentite spoglie? Non posso dire che la cosa mi sorprenda granché. I draghi sono sempre astuti.\n\nIl fatto che tu sia qui di fronte a me ora suggerisce che hai dovuto eliminare il drago, giusto? Non avrai lamentele da parte mia. Hai recuperato il diario e c'è un cattivo in meno nel mondo. Per me è una buona giornata di lavoro.\n\nGrazie, {name}.", 0x8db2fe13, 0x5484c229, 0x3a3ecf49, 0xcd98c2de, 0xe52edbd3, "....." },
  [96773] = { "L'Occhio dell'Araldo del Freddo", "Recupera l'Occhio dell'Araldo del Freddo dai ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.", "C'è un servitore del Re dei Lich che ha la sua dimora nel profondo della tana dei verrospini nota come ⟦Razorfen Downs=Sotterranei di Lamaspina⟧. Sappiamo che usa una sfera di scrutamento nota come \"L'Occhio dell'Araldo del Freddo\" per dirigere i movimenti dei suoi servitori minori altrove.\n\nEntra nei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧ e recupera l'Occhio dell'Araldo del Freddo per nostro conto, {class}. Il Kirin Tor pagherebbe profumatamente per ottenere questo artefatto, così da poterlo studiare e comprenderne il funzionamento interno.", "I metodi e i mezzi dei membri del Flagello sono misteriosi ed esoterici, persino per i colti maghi del Kirin Tor. Alcuni ipotizzano che la loro magia sia affine per natura alla magia elementale, forse una forza che agisce come antitesi della luce.\n\nAltri ipotizzano che la loro magia sia attinta dal regno degli spiriti stesso attraverso piccoli squarci nel velo tra la vita e la morte. Più manufatti del Flagello riusciamo a recuperare intatti per lo studio, più completa sarà la nostra comprensione.", "Hai fatto un buon lavoro. Come promesso, ecco la tua ricompensa.", 0x807d643a, 0xc02af882, 0x03f459cb, 0x6840ad2f, 0x18597913, "....." },
  [96774] = { "⟦Ancient Gurubashi Idol=Idolo Antico dei Gurubashi⟧", "Recupera un ⟦Ancient Gurubashi Idol=Idolo Antico dei Gurubashi⟧ dalla Drowned City.", "Gli antichi Gurubashi di Rovotorto erano maestri di oscura magia del sangue. Si dice che usassero idoli di verargento puro per incanalare quel voodoo cattivo cattivo.\n\nIl vecchio Mazu'kon darebbe qualsiasi cosa per mettere le mani su uno di quegli idoli... per studio, capisci. Che ne dici di radunare qualche amico e fare un bel colpo in quella città sommersa che spunta dal mare al largo della costa di Rovotorto? Uccidi il sacerdote dall'aria più importante che trovi là dentro, e di sicuro avrà quello che cerco.", nil, nil, 0x5f76897d, 0x4a847e99, 0xf74ccc84, nil, nil, "...mm" },
  [96775] = { "Testa di Zum'rah", "Uccidi il ⟦Witch Doctor Zum'rah=Taumaturgo Zum'rah⟧ e porta la Testa di Zum'rah a Mazu'kon a Mulgore.", "Il vecchio Mazu'kon ha un osso da spolpare con un santone che si chiama Zum'rah e io penso che tu puoi aiutarmi con questo.\n\nZum'rah pratica tutto il suo brutto voodoo nella città dei Sabbiafurente di ⟦Zul'Farrak=Zul'farrak⟧, molto a sud nei deserti di Tanaris. Vai là. Uccidi Zum'rah e portami la sua testa.\n\nFidati, il mondo sarà un posto migliore con la sua testa infilzata su una picca fuori dalla mia capanna che sulle sue spalle.", nil, nil, 0x8614fa93, 0x101e780b, 0x454a2ac8, nil, nil, "...mm" },
  [96776] = { "Radiosità di An'she", "Recupera il cristallo noto come Radiosità di An'she da Maraudon.", "Ho avuto una visione.\n\nNel profondo del luogo noto come Maraudon, oltre le cascate del canto della terra, c'è una camera piena di brillanti cristalli bianchi e custodita da possenti giganti. Nella parte più alta di questa camera c'è un cristallo di eccezionale splendore. È un aspetto del dio sole, l'occhio destro della stessa Madre Terra: An'she.\n\nHo sognato il suo splendore e mi chiama. {class}, porta via la Radiosità di An'she da quel luogo e portala qui, dove le appartiene, sotto i cieli aperti di Mulgore.", nil, nil, 0x29fa6e04, 0x3d4715f6, 0x1a4626c3, nil, nil, "...mm" },
  [96779] = { "Sabotaggio alla ⟦Syndicate=Lega dei Tagliagole⟧", "Trova Lord Tomas nel ⟦Durnholde Keep=Forte Durnholde⟧, sulle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, e uccidilo. Poi torna da ⟦Myrokos Silentform=Myrokos Silente⟧.", "A volte, {race}, basta un solo taglio nel punto giusto per stendere un nemico. Spesso vale lo stesso per le organizzazioni.\n\nI nostri agenti hanno individuato un bersaglio chiave tra le file della ⟦Syndicate=Lega dei Tagliagole⟧: un uomo di nome lord Tomas.\n\nHa un ruolo fondamentale nel funzionamento del ⟦Durnholde Keep=Forte Durnholde⟧, sulle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Se vuoi servire ⟦Ravenholdt=Corvolesto⟧, va' a Durnholde ed eliminalo. Più in fretta e in silenzio, meglio è.", nil, nil, 0x12459469, 0xd843986f, 0xd52e350a, nil, nil, "...mm" },
  [96781] = { "Che cosa avranno in mente?", "Ruba con destrezza il ⟦Barton's Scouting Report=Rapporto d'Esplorazione di Barton⟧ dalle tasche di Barton. Poi porta il rapporto a ⟦Myrokos Silentform=Myrokos Silente⟧ al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Abbiamo notato una squadra di esploratori della ⟦Syndicate=Lega dei Tagliagole⟧ che si aggira tra le rovine di Alterac, guidata da un uomo di nome Barton.\n\nÈ chiaro che stanno cercando qualcosa, ma non posso sapere cosa senza leggere i suoi rapporti di ricognizione.\n\nTi chiedo di sfilargli il rapporto dalle tasche, invece di ucciderlo. La morte di Barton farebbe capire alla ⟦Syndicate=Lega dei Tagliagole⟧ che li teniamo d'occhio, e di certo prenderebbero contromisure per coprire le loro tracce.\n\nSe vuoi trovarlo, molto probabilmente è con quelli della ⟦Syndicate=Lega dei Tagliagole⟧ a Strahnbrad.", nil, nil, 0xe4f9042e, 0x63217e37, 0x8e8d9103, nil, nil, "...mm" },
  [96782] = { "Recupero segreto", "Trova la ⟦Blade of House Perenolde=Lama del Casato Perenolde⟧ e l'⟦Royal Aegis of Perenolde=Egida Reale di Perenolde⟧ tra le rovine di Alterac. Poi portale a ⟦Myrokos Silentform=Myrokos Silente⟧.", "Pare che il nostro amico Barton ci abbia reso le cose molto facili. Cerca due cimeli della famiglia Perenolde tra le rovine di Alterac: la ⟦Blade of House Perenolde=Lama del Casato Perenolde⟧, una spada, e l'⟦Royal Aegis of Perenolde=Egida Reale di Perenolde⟧, uno scudo.\n\nDal rapporto, sembra che queste armi si trovino in due torri tra le rovine. Meglio prenderle prima della ⟦Syndicate=Lega dei Tagliagole⟧.\n\nGli ogre che occupano le rovine sono feroci, ma confido che saprai passare loro accanto senza dover sporcare di sangue la tua lama.", nil, nil, 0x38463dcf, 0x0dd136cc, 0xbaff77cb, nil, nil, "...mm" },
  [96783] = { "Una via d'accesso", "Ruba un'uniforme della ⟦Syndicate=Lega dei Tagliagole⟧ al ⟦Northfold Manor=Maniero dei Norten⟧ per infiltrarti nel ⟦Stromgarde Keep=Forte di Stromgarde⟧.", "Il ⟦Stromgarde Keep=Forte di Stromgarde⟧ è una delle roccaforti più grandi della ⟦Syndicate=Lega dei Tagliagole⟧. Molti degli affari più importanti dell'organizzazione si concludono dietro le sue mura.\n\nMi è giunta voce di un certo scambio tra membri della ⟦Syndicate=Lega dei Tagliagole⟧, da qualche parte negli ⟦Arathi Highlands=Altopiani d'Arathi⟧, e sono certo che i dettagli di questo scambio si trovino da qualche parte a Stromgarde.\n\nPer infiltrarti nel forte senza destare sospetti ti servirà un travestimento. Vedi se riesci a trovarne uno tra quelli della ⟦Syndicate=Lega dei Tagliagole⟧ fuori dal forte, al ⟦Northfold Manor=Maniero dei Norten⟧.", nil, nil, 0x1b0f8afe, 0xaa986c18, 0x7b8b0be2, nil, nil, "...mm" },
  [96784] = { "Maestro del travestimento", "Con il travestimento da membro della ⟦Syndicate=Lega dei Tagliagole⟧, trova qualcuno nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ che sappia dell'accordo segreto.", "<Ricordi le istruzioni di Myrokos: scoprire qualcosa su un affare importante della ⟦Syndicate=Lega dei Tagliagole⟧ nel ⟦Stromgarde Keep=Forte di Stromgarde⟧. Con il tuo travestimento dovresti poter parlare con i membri della ⟦Syndicate=Lega dei Tagliagole⟧ con una certa libertà. Di sicuro qualcuno di loro sa qualcosa.>", nil, nil, 0x87afd4b0, 0x839d37e0, 0xac13dcec, nil, nil, "...mm" },
  [96785] = { "Bocca cucita", "Trova qualcosa nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ che convinca Anastasia a rivelare i dettagli dell'accordo segreto.", "Chi ti credi di essere? Arrivi qui e ficchi il naso negli affari ufficiali.\n\nNon racconto niente a <un/una> pivell<o/a> sugli affari dei pezzi grossi senza un buon motivo. A meno che tu non abbia qualcosa di importante, o di prezioso, per me, non ho niente da dirti.", nil, nil, 0x21897a89, 0xe27114b7, 0xce26588b, nil, nil, "...mm" },
  [96786] = { "Trappola per la ⟦Syndicate=Lega dei Tagliagole⟧", "Manda all'aria l'accordo segreto e prendi l'oggetto destinato alla ⟦Syndicate=Lega dei Tagliagole⟧. Poi torna da ⟦Myrokos Silentform=Myrokos Silente⟧ al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Falconcrest ha mandato alcuni dei suoi a fare uno scambio nella parte meridionale del Muro di Thoradin. Non so cosa debbano ritirare. Dev'essere roba buona, perché tutti quelli coinvolti l'hanno tenuta segretissima. Credo che nemmeno quelli che la ritirano sappiano cos'è.\n\nÈ tutto quello che so. Non farmi pentire di avertelo detto.", nil, nil, 0x54ce55fd, 0x3c52e102, 0x27700057, nil, nil, "...mm" },
  [96796] = { "Officina nei boschi", "Porta il Pezzo di Ricambio all'inventrice nota come Kaylaena nella bassa Hyjal.", "Questo sembra qualcosa di cui potrebbe servirsi l'inventrice sulle colline, Kaylaena. Quasi non viene più a trovarci da quando ha perso la sua mentore, Yaely.\n\nCerca la sua officina sulle colline a nord. Dopo la caduta di Archimonde nella grande battaglia, le due recuperarono ciò che potevano riportare facilmente da sole, ripulendo molti dei macchinari su queste alture.\n\nDare nuovo uso a questi detriti è meglio che lasciarli arrugginire qui. La tua commissione aiuta a far germogliare nuova vita dove era soffocata dal metallo.", nil, nil, 0x918594f1, 0x5041b322, 0xeabc482c, nil, nil, "...mm" },
  [96797] = { "L'orfano", "Recati al ⟦Nethergarde Keep=Forte di Guardiafatua⟧ nelle ⟦Blasted Lands=Terre Devastate⟧ e trova il sergente Danneth.", "Spesso cerchiamo di trovare familiari superstiti per molti dei nostri assistiti e di tanto in tanto troviamo qualcosa di incoraggiante. Mi è giunta voce che Randal qui potrebbe avere un familiare in vita. L'uomo si chiama Danneth ed è un soldato di stanza al ⟦Nethergarde Keep=Forte di Guardiafatua⟧. Mi serve qualcuno che vada lì e trovi quest'uomo.\n\nSe puoi, convinci Danneth a venire a prendere suo nipote. Non credo che i due si siano mai incontrati, ma sono comunque una famiglia e Randal appartiene a lui.", nil, "Danneth? Mi dispiace dirtelo ma è scomparso da giorni.\n\nLa sua squadra è stata tesa in un'imboscata vicino alla Spina del Serpente. Non abbiamo mai recuperato un corpo, ma temo che le probabilità che sia ancora vivo non siano buone.", 0x06d9ea43, 0x3a64b856, 0x74fdcc7c, nil, 0xb004130d, "...m." },
  [96798] = { "Nell'oscurità", "Trova il sergente Danneth da qualche parte nelle caverne della ⟦Serpent's Coil=Spira del Serpente⟧, a sudest del ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", "Il sergente Danneth è stato visto l'ultima volta in pattuglia con la sua squadra vicino alla ⟦Serpent's Coil=Spira del Serpente⟧, subito a sud del ⟦Nethergarde Keep=Forte di Guardiafatua⟧. Uno dei membri della sua squadra è rientrato barcollando nel forte, gravemente ferito, sostenendo che l'intera squadra fosse stata uccisa o catturata. Quel soldato è morto poche ore dopo, purtroppo.\n\nNon abbiamo la conferma che Danneth sia morto, ma le probabilità non sono buone. Non posso risparmiare uomini per spingermi nella tana del culto, ma se volessi andare a cercare l'uomo, non rifiuterei l'aiuto.", nil, nil, 0x713cd83f, 0x9e8fb5bf, 0x0ff8b087, nil, nil, "...mm" },
  [96799] = { "Una pesante responsabilità", "Parla con il sergente Danneth al ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", "<Il tenente Connar ascolta mentre gli spieghi il motivo per cui sei qui.>\n\nQuindi Danneth ha un nipote orfano a Dalaran? Se non gliene hai ancora parlato, ti suggerisco di farlo. Non sembra proprio il tipo da genitore, ma potrebbe sorprendermi.\n\nSe vorrà andare a prendere il ragazzo una volta ristabilito, ha la mia benedizione per prendere un congedo a tale scopo.", nil, nil, 0xcd6be72b, 0x6157b976, 0xf44bbe90, nil, nil, "...mm" },
  [96800] = { "Restituzione in ritardo", "Recupera il libro ⟦The Lost Magic of the Runemasters=La Magia Perduta dei Maestri delle Rune⟧ dal ⟦Scarlet Monastery=Monastero Scarlatto⟧.", "Ehi, tu, {class}. Ho una faccenda per cui mi farebbe comodo un aiuto.\n\nGuarda caso sto scrivendo una tesi sugli antichi maestri delle rune Granmartello di Grim Batol, e mi serve un tomo in particolare per completare le mie ricerche. Secondo i nostri registri, un mago di nome Doan ha preso in prestito il libro dalla vecchia biblioteca di Dalaran prima della Terza Guerra e non l'ha mai restituito!\n\nL'arcanista Doan ora è rintanato nel ⟦Scarlet Monastery=Monastero Scarlatto⟧, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Recuperami quel libro e sarai ricompensat<o/a> a dovere.", "A volte mi sembra che questa tesi sia maledetta.", "Oh, hai dovuto uccidere Doan per riavere il libro? Oh no...\n\n... be', comunque, tutto è bene quel che finisce bene! Grazie per averlo restituito al suo legittimo posto e per avermi aiutato a finire la mia tesi. Sono piuttosto convinto che far rivivere l'arte perduta della magia runica dei nani sia ben alla nostra portata e intendo dimostrarlo!\n\nSe solo potessi entrare a Grim Batol e ispezionare di persona le incisioni runiche di un tempo...\n\nUn giorno, forse.", 0xc02ef2a8, 0x6080a32a, 0x72b14b39, 0x138cd656, 0x13aaa396, "....." },
  [96811] = { "Fuga dalle ombre", "Scorta il sergente Danneth fuori dalle caverne della ⟦Serpent's Coil=Spira del Serpente⟧ e di nuovo al ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", "Credo di essere pronto, ora. Andiamo quando vuoi.", nil, nil, 0xd6aa55ba, 0x81655720, 0x3205c370, nil, nil, "...mm" },
  [96812] = { "Il sangue non è acqua", "Torna dalla matrona dell'orfanotrofio Aria a Dalaran e informala dell'intenzione del sergente Danneth di prendere con sé Randal.", "Sì... sì, accoglierò il ragazzo. È famiglia e io sono tutto ciò che ha. Ho bisogno di riprendermi ancora un po', ma prenderò un congedo e partirò per Dalaran appena potrò.\n\nPer favore, torna dalla Matrona e dille che sto arrivando. Farò del mio meglio perché il figlio di mio fratello sia al sicuro e cresca forte.\n\nLo giuro.", nil, nil, 0x74278638, 0xd3e836dc, 0x813783b0, nil, nil, "...mm" },
  [96821] = { "Gambe in spalla", "Uccidi 6 Ridgeshade Creeper e 6 Ridgeshade Lurker nel sud di Durotar, poi fai rapporto a Gar'thok a ⟦Razor Hill=Tranciacolle⟧.", "Vediamo sempre meno viaggiatori da ⟦Razor Hill=Tranciacolle⟧, di questi tempi. Gli scorpidi non sono mai stati un granché, ma ora sento dire che ci sono ragni che fanno il nido lungo la strada.\n\nSe i tuoi viaggi ti portano a nord, uccidi qualche ragno lungo il cammino. Poi fai sapere a ⟦Razor Hill=Tranciacolle⟧ che la strada è un po' più sicura.", nil, "Da un po' di tempo i peoni hanno paura di viaggiare verso sud, {name}. Ora che hai ripulito un po' la strada, possiamo rimetterli al lavoro.", 0xb84a70d7, 0x3a400289, 0x05f6951d, nil, 0xd8c3f0b4, "...m." },
  [96822] = { "Per l'onore", "Raccogli l'⟦Raider's Battleaxe=Ascia da Battaglia dell'Incursore⟧, l'⟦Raider's Bow=Arco dell'Incursore⟧ e lo ⟦Raider's Shield=Scudo dell'Incursore⟧ nei dintorni del ⟦Tiragarde Keep=Forte di Tiragarde⟧, poi riportali a Turroc a ⟦Razor Hill=Tranciacolle⟧.", "Abbiamo perso molti valorosi guerrieri dell'⟦Horde=Orda⟧ quando abbiamo saccheggiato il ⟦Tiragarde Keep=Forte di Tiragarde⟧. Ora che gli umani hanno rinforzato le rovine, non possiamo recuperare le loro spoglie per onorarne degnamente la morte.\n\nVa' tra le rovine intorno al forte e cerca le armi lasciate dai nostri fratelli caduti. Le esporremo in un luogo d'onore.", "Hai fatto ciò che ti ho chiesto?", "Questi guerrieri saranno sempre ricordati, {name}. Te ne sei assicurat<o/a> tu.", 0x312a6de6, 0x12f27d5e, 0x59e8004e, 0x914533e6, 0xfc5f93be, "....." },
  [96825] = { "Un frutto che morde", "Il cuoco Torka di ⟦Razor Hill=Tranciacolle⟧ vuole che tu raccolga 8 ⟦Prickly Pear Fruit=Fico Spinoso⟧ nelle ⟦Razormane Grounds=Terre dei Chiomaguzza⟧, a ovest del villaggio.", "I nostri cacciatori e pescatori portano tanto cibo saporito per le truppe, ma è raro che portino qualcosa di dolce.\n\nHo visto un cactus che produce un frutto spinoso e gustoso. Ma cresce solo sulle colline a ovest, dove quei miserabili verrospini hanno i loro accampamenti. Supera i verrospini e portami un po' di quei frutti. E fa' attenzione: i frutti sono spinosi quanto i verrospini!", "Hai trovato i frutti?", "Li userò per preparare qualcosa di gustoso, e terrò da parte i semi per piantarli. Un giorno avremo fichi d'India in tutta Orgrimmar!", 0x5d0fb368, 0x56b9c042, 0x2c431c3a, 0xa390104c, 0x879b29b5, "....." },
  [96830] = { "Guidati dalla vista remota", "Cerca tracce dell'⟦Horde=Orda⟧ nel nordovest del ⟦Mount Hyjal=Monte Hyjal⟧.", "La mia ascia grondava ancora sangue di demone quando ho sentito un umano urlare molto in alto.\n\nHo alzato lo sguardo e ho visto quest'uomo penzolare tra gli artigli di una grande chimera. Ha lottato ferocemente, facendo perdere la presa alla bestia, che l'ha lasciato cadere.\n\nDa quell'altezza nessun guerriero si rialza. Anche i nemici meritano dignità, quindi l'ho trascinato all'ombra perché trapassasse in pace.\n\nDa parte mia, seguo le visioni dei veggenti: degli amici restano a Hyjal, molto a nord-ovest.\n\nTrova al mio posto quel che resta dell'⟦Horde=Orda⟧. L'onore mi vuole qui.", nil, nil, 0xcf7b38b1, 0xddcbdd46, 0x6134af41, nil, nil, "...mm" },
  [96833] = { "Fauci velenose", "Diffondi l'avvertimento sulla chimera aggressiva nota come Ghansurok agli altri sulla montagna.", "Gh... Ghan. Sur... Okk... Ghansurok. Questo è il nome della chimera vile. Pensavo di potermela cavare qui fuori... ugh... da solo. Nessuna possibilità. Mi ha portato in aria e mi ha ripulito.\n\nHo infilato il pugnale nell'occhio più vicino che sono riuscito a trovare e sono caduto più in basso delle cime degli alberi.\n\nNon sono stato l'unico ad aver fatto il passo più lungo della gamba questa volta. Haha... agh... non dovrei farmi ridere, fa già abbastanza male così.\n\nOssa spezzate potremmo aggiustarle, ma... il veleno... è troppo corrotto.\n\nTrasmetti un avvertimento. Ti prego!", nil, nil, 0x45916c91, 0xad3860db, 0xa460a2e5, nil, nil, "...mm" },
  [96873] = { "Un peso al collo", "Pa'zula, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, vuole che tu raccolga 3 ⟦Luminous Residue=Residuo Luminoso⟧. Il Luminous Residue si ottiene disincantando gli Hexed Pendant lasciati dai troll delle ⟦Echo Isles=Isole dell'Eco⟧.", "I troll a est di qui hanno perso la volontà per colpa del santone Zalazane. Usa molte magie crudeli per tenere in pugno la mente dei suoi prigionieri, ma uno dei suoi trucchi preferiti è fargli indossare pendenti avvolti da malvagi incantesimi di vincolo.\n\nEsercita le tue abilità di incantamento spogliando questi pendenti della loro magia, e portami i risultati. E non metterne uno al collo per sbaglio, se ci tieni alla tua libertà!", "Che cos'hai per me, {name}?", "Ottimo lavoro. Peccato per i troll uccisi, ma ora che gli incantesimi di vincolo sono stati rimossi, i loro spiriti possono riposare.", 0xdbeec7f9, 0x2e3399cb, 0x4f2abab1, 0x777ed8a4, 0xd6297264, "....." },
  [96874] = { "L'ascia spinosa", "Ug'thok, a Orgrimmar, vuole che tu raccolga 5 Weathered Spine dalle bestie della ⟦Thunder Ridge=Fossa del Tuono⟧, insieme a 5 Pietra da Molatura Grezza.", "Hai visto le enormi bestie della ⟦Thunder Ridge=Fossa del Tuono⟧? Continuo a pensare che gli aculei sulla loro schiena sarebbero perfetti per forgiare la testa di una possente ascia. Saru si è messo a ridere quando gliel'ho detto... ma che ne sa lui!?\n\nCome parte delle tue lezioni di forgiatura, puoi darmi una mano! Portami un po' di quegli aculei, insieme a delle pietre da molatura per affilarli.", nil, nil, 0xf6bb3113, 0xf3ac90a4, 0xc9a1f75b, nil, nil, "...mm" },
  [96875] = { "Le bestie della ⟦Thunder Ridge=Fossa del Tuono⟧", "Kamari, a Orgrimmar, vuole che tu raccolga 5 ⟦Rough Lizard Hide=Pelle di Lucertola Grezza⟧ dalle bestie della ⟦Thunder Ridge=Fossa del Tuono⟧, insieme a 2 Pelle Leggera Trattata.", "Orgrimmar non smette mai di crescere, {class}. E quando i peoni hanno bisogno di pelli per rivestire le pareti e i tetti dei nostri nuovi edifici, vengono da me!\n\nLe pelli delle lucertole della ⟦Thunder Ridge=Fossa del Tuono⟧ di solito sono troppo spesse per farne armature, ma sono un ottimo materiale da costruzione. Portami un po' delle loro pelli, insieme a qualche pelle leggera trattata. Vediamo come te la cavi con il cuoio!", nil, nil, 0x6150b99e, 0x6f6f97d3, 0x8796ce18, nil, nil, "...mm" },
  [96876] = { "Lo zaino perduto di Ukor", "Riporta lo zaino a Ukor, nel sud di Durotar.", "Sulla patta dello zaino è cucito alla buona il nome \"Ukor\".", nil, nil, 0xae92df38, 0x533f75f6, 0x6bd7c611, nil, nil, "...mm" },
  [96877] = { "Lo zoccolo di Halikor", "Consegna lo ⟦Halikor's Hoof=Zoccolo di Halikor⟧ a Orgrimmar.", "L'enorme zoccolo è la prova della tua vittoria sulla possente lucertola.", "Sì?", "Che trofeo, {class}! Dev'essere stato un bel combattimento!", 0x795887e1, 0xda5a81ff, 0x4475e6e3, 0x0c07a888, 0x6e0703c3, "....." },
  [96895] = { "L'emissario dell'Alba d'Argento", "Trova il membro dell'⟦Argent Dawn=Alba d'Argento⟧ nei pressi dell'ingresso di ⟦Undercity=Sepulcra⟧.", "Non so se l'hai saputo, ma due emissari dell'⟦Argent Dawn=Alba d'Argento⟧ sono appena passati di qui. L'⟦Argent Dawn=Alba d'Argento⟧ non mi dispiace, ma non mi piace nemmeno che ficchino il naso a Tirisfal senza sorveglianza. Erano tutti e due Reietti... ma questo non mi rende meno nervoso.\n\nUno di loro è appena passato di qui, diretto a sud-est. In quella direzione c'è un gruppo di cultisti del Flagello che curiosa ai margini della città. Se quei due ne hanno sentito parlare, non c'è dubbio che abbiano attirato la loro attenzione.", nil, "Tieniti bass<o/a> e cerca di non farti vedere, {class}. Con questi cultisti non si scherza.", 0xdf68a7ca, 0x2508ce6f, 0x46ae3d29, nil, 0x5a1a2923, "...m." },
  [96896] = { "Una giusta causa", "Assisti alla conversazione tra Danitha Morr e ⟦Leonid Barthalomew the Revered=Leonid Bartholomew il Riverito⟧.", "Danitha e io abbiamo combattuto contro il Flagello in difesa di ⟦Undercity=Sepulcra⟧, quando Naxxramas ha attaccato. Quel giorno abbiamo perso molti buoni amici, compreso l'eroe da cui prende il nome questa fortezza: Garek Bandarion.\n\nForse è stato il primo Reietto a riscoprire come brandire la Luce da paladino. Mi conforta vedere la sua eredità e il suo potenziale continuare a vivere qui, con Danitha e i suoi compagni.\n\nSe solo il resto dei Reietti la pensasse allo stesso modo...", nil, "Ho intenzione di restare qui per un po' a parlare con altri amici, ma presto tornerò alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Se mai ti capitasse di passare da quelle parti, vieni a salutarmi. Un aiuto da avventurieri capaci ci fa sempre comodo.", 0xb14e63d6, 0x07dc792c, 0x3aaba567, nil, 0xf3a7963d, "...m." },
  [96897] = { "Il ⟦Cult of the Damned=Culto dei Dannati⟧", "Uccidi $N1 Dark Neophyte e $N2 Dark Enforcer nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Il Flagello è una piaga per le nostre terre, e i suoi servitori vivi sono i peggiori di tutti. La gente di Tirisfal ha già abbastanza da fare tra i morti senza mente e la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Se vuoi fare del bene, aiutami a farla finita con questa feccia.", "Provo un disgusto particolare per i servitori viventi del Flagello. Hanno il libero arbitrio di andarsene, eppure la promessa di potere e immortalità li ha privati della ragione e della moralità.", "Grazie per il tuo aiuto, {class}. Se non vogliamo che la storia di Lordaeron si ripeta, dobbiamo restare vigili quando spuntano minacce come questa.", 0xb7d2480d, 0x5e8b58f6, 0xcef83677, 0x5254018a, 0x346b816b, "....." },
  [96898] = { "Resti della guerra", "Raccogli $N1 Necrotic Crystal Fragment nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Non molto tempo fa la cittadella di Naxxramas incombeva su questa città, decisa a cancellare i Reietti dalla faccia della terra. Sia i Reietti sia l'⟦Argent Dawn=Alba d'Argento⟧ persero molto, quel giorno, per assicurare il futuro dei Reietti.\n\nDurante la battaglia, il grande cristallo focalizzatore necrotico montato in cima a Naxxramas andò in frantumi e i suoi frammenti si sparsero per tutta questa zona. Sospetto che i cultisti siano qui proprio per questo. Aiutami a recuperare i frammenti e a sottrarli al Flagello.", "Ti consiglio di non toccare troppo quei cristalli. Anche frantumati ed esauriti, la magia residua di questi cristalli necrotici è molto pericolosa.", "Grazie. Questo dovrebbe rallentare gli sforzi del Flagello in questa zona. Sospetto che gli abitanti di Tirisfal continueranno a tirare fuori questi cristalli dal terreno per anni, ma togliere quelli più in vista non può che aiutare.", 0x91003497, 0x26a56997, 0x244a6298, 0x408b3f9b, 0x894f0f43, "....." },
  [96899] = { "⟦Bandarion Keep=Forte Bandarion⟧", "Incontra Leonid Barthalomew a ⟦Bandarion Keep=Forte Bandarion⟧, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Oggi hai fatto una gran cosa per la causa dell'⟦Argent Dawn=Alba d'Argento⟧, e te ne ringrazio. Non so quanto tu conosca la fortezza di ⟦Bandarion Keep=Forte Bandarion⟧, ma io e il mio comandante eravamo diretti laggiù per incontrare i paladini che vi risiedono. Questo prima di scoprire la presenza del Cult of the Damned.\n\nSe vuoi saperne di più sull'⟦Argent Dawn=Alba d'Argento⟧ e sulla nostra missione, cerca il mio comandante a ⟦Bandarion Keep=Forte Bandarion⟧, a nord-ovest di qui. Io resterò qui a ripulire il resto di questo pasticcio.", nil, "Questo luogo è pieno di ricordi per me. Un tempo era in mano all'⟦Argent Dawn=Alba d'Argento⟧. Fu da qui che ci preparammo a molte battaglie e scaramucce contro il Flagello, durante la sua ultima avanzata nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.\n\nQuando ci ritirammo nelle ⟦Plaguelands=Terre Infette⟧ temevo che sarebbe andato in rovina. Il mio timore era fondato, ma sono lieto che Danitha e i suoi paladini se ne siano ora presi cura.\n\nHa persino dato al forte il nome di... un amico comune.", 0x48578fb3, 0x80cd9bdb, 0x27457914, nil, 0x17570e1d, "...m." },
  [96912] = { "Campo dell'onore: settimana 1", "Vinci 10 duelli.", "Ehi amico, avvicinati pure! Hai l'aria di uno che sa da che parte si impugna la spada!\n\nPer puro caso ho una lunga lista di sfide che solo i combattenti più d'élite riusciranno a completare. Ti va di provarci?", nil, nil, 0xfe280b34, 0xc8fd5d0d, 0x8e3c78da, nil, nil, "...mm" },
  [96913] = { "Campo dell'onore: settimana 2", "Completa 3 battaglie nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "Di nuovo tu, eh? Sei <pronto/pronta> per la prossima prova? Spero che tu non sia schizzinoso. Potresti dover sanguinare per questa... o meglio far sanguinare prima gli altri.", nil, nil, 0xfe280b35, 0xb9209b33, 0x90a36567, nil, nil, "...mm" },
  [96914] = { "Campo dell'onore: settimana 3", "Uccidi 25 giocatori della fazione nemica nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "Vedo del potenziale qui. Questa prossima sfida ti richiederà di sporcarti davvero le mani. Spero che tu sia all'altezza!", nil, nil, 0xfe280b36, 0x7562eb20, 0xaa27f044, nil, nil, "...mm" },
  [96930] = { "Il Corvide Capriccioso", "Torna dal Corvo Curioso.", "Ci serve davvero una magia potente per contrastare la forza che ora Ve'han Presartiglio comanda. Il bastone che Velician ha sottratto potrebbe essere proprio la chiave.\n\nI miei poteri di druido non sono più quelli di un tempo. Ci servirà l'aiuto degli abitanti divini della montagna per fermare questo male.\n\nTorna dal corvo che hai incontrato su per la montagna. È saggia ma gli spiriti della natura selvaggia sono sempre capricciosi, anche di fronte a minacce terribili. Può essere difficile, ma avremo bisogno del suo aiuto.", nil, nil, 0x7026db36, 0x2e21bcfe, 0x639c3012, nil, nil, "...mm" },
  [96931] = { "Verso la cima della montagna", "Tocca l'Effigie del Corvo sul ponte che domina la Culla della Tranquillità per chiamare il Dio Selvatico, Jereman.", "Ascolta, terricolo. Sono, naturalmente, nota per intelletto e arguzia, ma ce n'è una ancora più maestosa e potente di me.\n\nParlo, naturalmente, della più astuta, scaltra e graziosa tra gli Dei Selvatici, Jereman! Ogni uccello conosce il suo nome ed è saggia ben oltre la sua apertura alare. Di certo saprà cosa serve per la magia di quel vecchio sasso.\n\nNidifica in quella che voi terricoli chiamate Culla della Tranquillità. Tocca l'effigie del corvo sul vecchio ponte e lei potrebbe apparire!", nil, nil, 0xceba0759, 0xa576d66f, 0x9c7b7fcc, nil, nil, "...mm" },
  [96939] = { "L'equilibrio tra vita e morte", "Parla con il Dio Selvatico, Marrosis.", "Credo che uno dei miei buoni amici possa avere un'idea per una fonte di potere aggiuntiva per la mossa di Ketharas.\n\nÈ un caro amico, naturalmente, e sarà entusiasta di prestare il suo aiuto a un agente della mia volontà come te!\n\nTrovi quel vecchio puzzapiume nella zona a sud di qui infestata dai non morti. Riposo del Lutto, mi pare che lo chiamiate voi mortali?\n\nAssicurati di dire che ti mando io! Gli PIACERÀ... senza dubbio!", nil, nil, 0x41e7f749, 0x22f1ab29, 0x9414b433, nil, nil, "...mm" },
  [96957] = { "Dolce osso, dolce casa", "Raccogli $N1 Osso Sbiancato dal Sole.", "Ascolta, mortale. Anche se può non sembrare un lavoro glorioso, chi è sotto la mia ala aiuta a mantenere l'equilibrio naturale. Restituiamo al suolo molti nutrienti essenziali, permettendo nuova vita.\n\nQuesti non morti hanno interrotto il ciclo qui e hanno scacciato chi cerca riparo sotto le mie ali. Mentre sei là fuori a fare la piccola creatura assassina che sei, potresti raccogliere delle ossa per me?\n\nVorrei ricostruire i nidi dei miei figli e seguaci così da poterci banchettare quando questa piaga sarà finita.", nil, nil, 0xd411e8a7, 0x14ee20c3, 0x8da62d90, nil, nil, "...mm" },
  [96959] = { "I falò del maestro di spade", "Accendi i due falò a Dae'gun e torna da Yashiro.", "Guerra.\n\nQuando ho risposto alla chiamata dei nostri clan, la battaglia era passata e solo le ceneri hanno risposto alla mia lama.\n\nIl mio scopo è forgiato di nuovo.\n\nQuesta montagna ricorda la forza: un antico potere cavalca i suoi venti e custodisce le sue acque. Vorrei guadagnarmi il diritto di percorrere la sua spina dorsale, di raggiungere la roccaforte caduta che giace lungo la strada verso la vetta.\n\nI demoni profanano queste tombe. Prima di combattere al tuo fianco, devo sapere che sei capace. Accendi i due falò e torna da me. Le loro fiamme attireranno il nostro nemico.", nil, nil, 0x6ddccd05, 0x271f18a0, 0x0cf974dc, nil, nil, "...mm" },
  [96964] = { "Una creatura astuta", "Parla con il Dio Selvatico Renalard.", "Se l'eremita vuole davvero che la sua piccola mossa lasci il nido e voli, avrà probabilmente bisogno di una potente fonte di energia. Una che possa sostenersi da sola senza crollare.\n\n<Jereman guarda il cielo e batte il becco mentre riflette.>\n\nAh, sì. So proprio quale astuta creatura possiamo consultare. Va' a nord, nella zona che voi mortali chiamate Dae'gun, quella con i demoni, e cerca la volpe, il Dio Selvatico Renalard. Credo che avrà una soluzione al nostro piccolo enigma.", nil, nil, 0xcb2372fd, 0xfb7c78fb, 0xc6e18bf1, nil, nil, "...mm" },
  [96971] = { "Fregare un demone", "Raccogli $N1 Scorte Abbandonate.", "Dimmi, mentre ti aggiri saltellando nelle mie terre, ti dispiacerebbe farmi un favore?\n\nUna volta vinta la guerra, molti dei vari eserciti se ne sono andati. Per qualche motivo hanno deciso che alcune delle loro provviste non valevano la pena di essere portate via. Oppure sono morti tutti. Chi può dirlo?\n\nIn ogni caso, queste provviste servono ai miei cuccioli e a me. Purtroppo tendono anche a trovarsi dove ci sono i demoni. Porta con te questo ciuffo di pelo e usalo sui demoni per distrarli mentre prendi gli attrezzi.", nil, nil, 0x8a1c54ab, 0x3d8fcac2, 0xba6994f0, nil, nil, "...mm" },
  [96978] = { "Cacciagione violenta", "Parla con il Dio Selvatico, Kala'th.", "Da quando quei brutti druidi di Spinanera sono saliti al potere, molti degli dei meno potenti qui a Hyjal hanno... beh, a essere schietti, hanno cercato di sovvertire l'ordine naturale delle cose.\n\nIl peggior trasgressore è Kala'th.\n\n<Jereman alza gli occhi al cielo.>\n\nQuella sciocca cerva si crede, lei e il suo branco, un predatore. Di nuovo.\n\nNon fraintendermi, all'inizio era piuttosto divertente, ma ora è il momento di rimettere le cose in ordine.\n\nVai a parlarle per vedere se riesci a farla ragionare, per favore.", nil, nil, 0xfb4b81d5, 0x82f85488, 0x6a1b100a, nil, nil, "...mm" },
  [96979] = { "Rinfresco sacro", "Riempi la borraccia di Galvinquam Leafsyre alla cascata più avanti.", "Sono un druido del Circolo, e percorro il lungo cammino per onorare il grande albero del mondo. Ho giudicato male quanto mi avrebbe richiesto la salita, e i cacciatori alati che infestano questi pendii hanno reso la cautela una necessità. Queste vecchie rovine mi hanno offerto riparo e io l'ho accettato.\n\nQuesto luogo è adatto a una modesta offerta, ma nessun rituale dovrebbe essere compiuto senza acqua viva. Se ti va, riempi la mia zucca alle cascate più avanti.\n\nQuando torni, parlami del sentiero che hai percorso e di ciò che si muove lungo di esso.", nil, nil, 0xcef841cb, 0x6ed72776, 0xca1f2562, nil, nil, "...mm" },
  [96982] = { "Il tuo primo ⟦Riding Kodo=Kodo Cavalcabile⟧", "Ispeziona i Kodo Cavalcabili per scegliere la tua prima cavalcatura.", "Ah, ti aspettavo, {class}. Sembra che i venti ti abbiano portato da me oggi. Sei qui in cerca di un kodo, giusto?\n\nIl kodo è una nobile bestia lenta all'ira e difficilmente troveresti un compagno più affidabile.\n\nOggi hai una scelta importante da fare. Tu e il tuo kodo viaggerete insieme per il mondo, quindi trova quello che ti parla. Non temere, qualunque scelta farai sarà quella giusta.\n\nVai a esaminare i kodo e torna da me quando avrai deciso.", nil, nil, 0x2f8c7c80, 0x9ca0fd73, 0xb649c7a4, nil, nil, "...mm" },
  [96983] = { "Il Passovento di Yashiro", "Fatti strada combattendo a Dae'gun insieme a Yashiro.", "Sei capace, veloce, senza paura. Il fuoco trarrà i demoni dai loro nascondigli e, con loro, i loro signori della guerra. Verranno in cerca di dominio. Troveranno invece ad attenderli la vendetta. Questo è il momento in cui la volontà della montagna parla attraverso di noi.\n\nVieni, apriamoci un varco tra questi demoni e poniamo fine al loro regno. La mia lama brama di fendere i loro ranghi.", nil, nil, 0x727b69f3, 0x30aead77, 0xc9314578, nil, nil, "...mm" },
  [96984] = { "Il cuore dello sconvolgimento", "Raccogli la ⟦Arcane Mote=Particella Arcana⟧ nella città di Dalaran per il magus Wordeen Bagliovuoto, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Forse non hai a cuore i nostri interessi, ma non rifiuterò un paio di mani in più. E se Dalaran cade, trascina con sé tutto quanto, compresa la tua ⟦Undercity=Sepulcra⟧.\n\nDunque il tuo benefattore vuole entrare? D'accordo. Infonderò la tua chiave perché superi le mie protezioni, così potrai entrare in città. Una volta dentro, raggiungimi alla Violet Citadel, dove è cominciato tutto. Con tutto quello che sta succedendo, il Kirin Tor sarà troppo occupato per fermarti.\n\nArraffa quello che vuoi, ma qualunque cosa accada, la nostra priorità è evitare una catastrofe.", "Hai fatto bene a tornare subito da me. Hai trovato qualcosa a Dalaran?", "Oh, cielo, un'ombra dell'arcimago? Che imbarazzo assoluto per loro.\n\nE il Kirin Tor ti ha fatto entrare nelle loro stanze interne? Interessante. Questo potrebbe offrire un'opportunità...", 0x0ac2f4b9, 0xe3ed9b69, 0x6b205a30, 0xc37f8407, 0xb9525ab7, "....." },
  [96986] = { "Il cavaliere delle tombe", "Sconfiggi Atrexis the Grave Knight nella città di Dalaran per Melisara, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Nelle viscere della città dei maghi, a nord, si nasconde un traditore della nostra specie. Un negromante di inquietante talento. Sta radunando un esercito di non morti proprio sotto il naso del Kirin Tor.\n\nNon m'importa della sorte della città dei maghi, {name}, ma questo cavaliere delle tombe sputa in faccia a tutto ciò che noi Reietti rappresentiamo. Fallo fuori. Mostragli che nessuno è fuori dalla portata della Dama Oscura.", "L'hai fatto?", "Ottimo lavoro. Quella bestia non è degna di camminare tra i morti. Che giaccia sotto di loro.", 0x9b982b21, 0x24bf35e3, 0x65fb9835, 0x3f3508e7, 0x68b23b00, "....." },
  [96987] = { "Un'istruzione opportunista", "Recupera il Founding of Dalaran nella città di Dalaran per Rexxie Copperclutch, vicino all'ingresso delle fogne.", "Ma guarda, qualcuno che la pensa come me in fatto di affari. Intrufolarsi a Dalaran in tempi così burrascosi? Tsk tsk.\n\n<Un/Una> {race} come piace a me!\n\nMentre i nostri amici maghi sono occupati, magari potremmo trovarci qualche tesoro «smarrito». Hanno intere biblioteche dedicate alle loro raffinate magie arcane. Se mi porti uno dei loro tomi segreti, potrei rivenderlo a peso d'oro. E dividiamo i profitti.\n\nEhi, ehi, non guardarmi così. Neanche tu sei qui in gita scolastica. Ci stai o no?", "Allora? L'hai trovata la loro biblioteca? Ci dev'essere qualcosa di buono là dentro.", "Forse non avrei dovuto mandare un tirapiedi a cercare manufatti inestimabili. Questo vale a malapena la pena di venderlo in un chiosco per turisti! Che hai fatto, hai preso il primo libro che sporgeva dagli altri?\n\nLascia perdere. Magari posso spruzzarlo d'oro e dire che apparteneva a un arcimago o roba simile.", 0xcb4d2d84, 0xc41dad65, 0x159f4617, 0x19998649, 0xdb720c34, "....." },
  [96988] = { "Fonte di potere", "Raccogli $N1 Cracked Sentry Core nella città di Dalaran per il dottor Martin Felben, a ⟦Undercity=Sepulcra⟧.", "Con la città di Dalaran assediata dai suoi stessi costrutti, è l'occasione perfetta per, diciamo, prendere in prestito qualche campione.\n\nImmagina un esercito di abomini alimentati dall'arcano. La Dama Oscura non avrebbe altra scelta che riconoscere la mia abilità alchemica. Magari mi metterebbe perfino a capo della Royal Apothecary Society?\n\nVa' in città e trova i nuclei dei costrutti. Difficilmente te li daranno di loro spontanea volontà, quindi fa' ciò che devi.", "Il pregio di questi nuclei è che sono potenti. Il guaio è che, per lo stesso motivo, sono potenti anche i costrutti. Buona fortuna.", "Incrinato. Incrinato. INCRINATO.\n\nNon posso usarne neanche uno! Ti avevo detto di disattivare le sentinelle, non di annientarle! Quanto potevano essere pericolose?\n\nI miei sogni di abomini arcani sono in stallo. Per ora.", 0x64b20fc1, 0x8337ed29, 0xa537f845, 0x406d6cfd, 0xb95a6f40, "....." },
  [96989] = { "Il tuo primo ⟦Riding Raptor=Raptor Cavalcabile⟧", "Ispeziona i Raptor Cavalcabili per scegliere la tua prima cavalcatura.", "Ehi amico! Oggi per te è un gran giorno, vedo. Pensi di essere pronto a prendere le redini di una di queste feroci creature, eh?\n\nIn tanti sottovalutano quanto siano intelligenti e selvagge queste bestie. Non troverai un compagno migliore, più veloce o più letale una volta legato a lui.\n\nQuindi hai una scelta importante da fare. Il tuo raptor e tu viaggerete insieme per il mondo, e anche il raptor dovrà scegliere te in cambio.\n\nVai a dare un'occhiata e torna da me quando hai deciso.", nil, nil, 0x5d01635c, 0xd621c0a6, 0xee32bad6, nil, nil, "...mm" },
  [96991] = { "Assistenza sul sentiero", "Consegna gli Effetti Personali di Galvinquam a Marn Euhron alla Sommità.", "La salita si fa più ripida da qui, come dici. Anche uno zaino vuoto pesa su gambe stanche. Ti chiederei un altro favore, viaggiatore. Prendi la mia attrezzatura in eccesso e portala avanti alla Sommità, dove Marn Euhron aiuta a ripristinare un punto d'appoggio vicino a Nordrassil.\n\nTi seguirò con i miei tempi quando le mie cerimonie qui saranno concluse. Quando arriverò, la riprenderò da lui e lo aiuterò nel suo lavoro. In questo modo onoriamo entrambi il viaggio e i doni della montagna.", nil, nil, 0x0487ac9f, 0x9af8f93c, 0x274078c3, nil, nil, "...mm" },
  [96992] = { "Rifornimento", "Cerca tra gli edifici bruciati nella Culla della Tranquillità $N1 Staffa di Metallo e $N2 Chiodo, poi torna da Johun \"Cazzotto\" Dillas a Hyjal.", "Sai, hanno portato abbastanza attrezzi per avviare l'essenziale, ma non c'è mai abbastanza materiale di fissaggio. Le mie mani non reggono più di tanto a legare corde.\n\nL'ingegno è ancora meglio dell'essere preparati.\n\nPrendi una borsa vuota e vai ai resti bruciati degli edifici dell'Alleanza intorno alla Culla della Tranquillità a sud-ovest di qui, e riempila con quanti più chiodi e staffe riesci a trovare tra le ceneri.", nil, nil, 0x9e2e3b44, 0x4554daea, 0xb9dd50a4, nil, nil, "...mm" },
  [96994] = { "Il tuo primo ⟦Riding Wolf=Lupo Cavalcabile⟧", "Ispeziona i Lupi Cavalcabili per scegliere la tua prima cavalcatura.", "Lok'tar, {class}. Sei qui per legarti al tuo primo lupo? Bene.\n\nNon esiste legame più forte di quello tra un orco e il suo lupo. Non sono semplici cavalcature, ma compagni e amici per tutta la vita.\n\nIl nostro non è un legame scelto per vanità. No, ogni orco e ogni lupo formano un legame speciale che va oltre un semplice acquisto.\n\nTi sceglieranno tanto quanto tu sceglierai loro. Lo capirai quando li incontrerai.\n\nVai a cercare quale lupo ti parla. Torna da me quando avrai la tua risposta.", nil, nil, 0x312823d3, 0x8e279f41, 0xc1cfe1ad, nil, nil, "...mm" },
  [96996] = { "Il tuo primo Calcaventi da cavalcare", "Ispeziona i Calcaventi da cavalcare per scegliere la tua prima cavalcatura.", "Ora che hai completato il tuo addestramento, sembra che i venti desiderino che tu ti leghi al tuo primo corridore.\n\nQuesti corridori del vento sono stati cavalcati dai nostri antenati per generazioni. Nonostante l'aspetto etereo e slanciato, sono cavalcature salde e feroci.\n\nTu e il tuo corridore viaggerete insieme per il mondo, quindi hai una scelta importante da fare. Non temere, qualunque scelta farai sarà quella giusta.\n\nVai a esaminare i corridori e torna da me quando avrai deciso.", nil, "Eccellente, {name}. Vedo nei tuoi occhi che hai fatto una scelta.\n\nDevo dire che quello che hai scelto sembra già affezionato a te, e sarà bello avere con te un ricordo di casa mentre le tue avventure ti porteranno lontano da Zephras. Spero che ti prenderai buona cura di lui, e lui di te.\n\nChe i venti vi guidino entrambi!", 0x0451b7f8, 0xd4f44937, 0x11448014, nil, 0x02add09c, "...m." },
  [96997] = { "Un destriero in morte come in vita", "Ispeziona i cavalli non morti da cavalcare per scegliere la tua prima cavalcatura.", "Salute, {class}. Immagino di poter indovinare cosa ti ha portato alle mie stalle oggi.\n\nSe cerchi una cavalcatura, sei nel posto giusto. Sappi però che cavalcare un destriero non morto non è per i deboli di cuore.\n\nPerciò hai una scelta importante da fare. Tu e il tuo destriero non morto viaggerete insieme per il mondo nel bene o nel male. Non temere, qualunque scelta farai sarà quella giusta.\n\nVai a esaminare i cavalli non morti e torna da me quando avrai deciso.", nil, nil, 0xcea878f9, 0x3be62de1, 0xacfdae3d, nil, nil, "...mm" },
  [96998] = { "Colori tribali", "Porta la Fascia del Pittore di Guerra a qualcuno che potrebbe riconoscerla.", "Lo scheletro che stringe ancora una lancia da lancio mostra i segni inconfondibili di un cacciatore di teste troll.\n\nIn una delle sue mani ossute c'è una fascia di cuoio adorna di caratteri troll e macchie di colori per il viso nelle tinte dei ⟦Darkspear=Lanciascura⟧. Doveva essere una sacca per il trucco usata per applicare la pittura di guerra.\n\nI membri della tribù dei ⟦Darkspear=Lanciascura⟧ potrebbero riconoscere la scrittura sulle pelli sacre.", nil, nil, 0xfbe8a5d2, 0xa798a01b, 0x91d746c5, nil, nil, "...mm" },
  [96999] = { "Restituire la fascia", "Porta la Fascia del Pittore di Guerra a qualcuno al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Chiunque indossasse questo ha combattuto con uno scopo. E Sen'jin è un piccolo villaggio... sangue e parentela sono vicini lì.\n\nQualcuno a casa sente la mancanza di questa fascia, e del guerriero che la portava.\n\nQuando vai alle ⟦Echo Isles=Isole dell'Eco⟧, porta con te questa fascia. Riportala a Sen'jin. Sapranno a chi apparteneva, e ti renderanno onore per averla fatta tornare.", nil, nil, 0x8926bb2c, 0x6e7f2ad0, 0x8c6bab1d, nil, nil, "...mm" },
})
